// ===========================================================================
//  TEST CASES  —  POST /platform/schools/{id}/complete-provisioning
//
//  This endpoint takes NO BODY. It is a POST because it performs an action,
//  not because it sends data. The {id} comes from the URL.
//
//  So the cases below are about which {{schoolId}} you point it at, and what
//  state that school is in. Set the variable, then Send.
//
//  Safe to send as-is: the controller has no @RequestBody, so Spring ignores
//  whatever is here even if your Postman does not strip comments.
// ===========================================================================
//
// ---------------------------------------------------------------------------
// 01  FIRST CALL on a freshly created school              -> 200 OK
//     Run "Create School" first — it saves {{schoolId}}.
//     OUT: numberSequencesCreated: 47,  numberSequencesAlreadyPresent: 0
//          rolesCreated: 3,             rolesAlreadyPresent: 0
//          roleKeys: ["GUARDIAN","SCHOOL_ADMIN","TEACHER"]
//          readyToActivate: true
// ---------------------------------------------------------------------------
//
// ---------------------------------------------------------------------------
// 02  SEND IT AGAIN — idempotency                         -> 200 OK
//     Same {{schoolId}}, no changes needed. Nothing is written.
//     OUT: numberSequencesCreated: 0,  numberSequencesAlreadyPresent: 47
//          rolesCreated: 0,            rolesAlreadyPresent: 3
//          readyToActivate: true
//
//     Still 200, not 201. A call that created nothing because everything was
//     already there is a success — 201 Created would be a lie.
// ---------------------------------------------------------------------------
//
// ---------------------------------------------------------------------------
// 03  PARTIAL REPAIR — the case this endpoint exists for  -> 200 OK
//     Delete some rows in MongoDB first, then send again:
//
//       db.number_sequences.deleteMany({schoolId: "<id>", sequenceType: "FEE_INVOICE"})
//       db.roles.deleteOne({schoolId: "<id>", roleKey: "TEACHER"})
//
//     OUT: numberSequencesCreated: 1,  numberSequencesAlreadyPresent: 46
//          rolesCreated: 1,            rolesAlreadyPresent: 2
//
//     It fills only the gaps. An existing role is skipped, never overwritten —
//     so a school that edited SCHOOL_ADMIN's permissions keeps them.
// ---------------------------------------------------------------------------
//
// ---------------------------------------------------------------------------
// 04  UNKNOWN SCHOOL ID                                   -> 404 Not Found
//     Set {{schoolId}} to 6a90000000000000000000aa
//     OUT: { "code": "SCHOOL_NOT_FOUND",
//            "message": "No school found with id '...'." }
// ---------------------------------------------------------------------------
//
// ---------------------------------------------------------------------------
// 05  SHUT-DOWN TENANT                                    -> 409 Conflict
//     Set the school to an end-of-life status first:
//
//       db.schools.updateOne({_id: ObjectId("<id>")}, {$set: {status: "CLOSED"}})
//
//     OUT: { "code": "SCHOOL_NOT_PROVISIONABLE",
//            "message": "A school at status CLOSED cannot be provisioned." }
//
//     Refused for OFFBOARDING, CLOSED, DELETION_PENDING and DELETED. Seeding
//     one would quietly bring rows back to a school somebody deliberately shut
//     down. Every other status is allowed, including ACTIVE — so a school found
//     to be missing a role after go-live is fixed here, not by hand in the
//     database.
// ---------------------------------------------------------------------------

// ===========================================================================
//  TEST CASES  —  POST /platform/schools/{id}/activate
//
//  No body. The {id} comes from the URL, so the cases below are about which
//  {{schoolId}} you point it at and what state that school is in.
//
//  Safe to send as-is: the controller has no @RequestBody, so Spring ignores
//  whatever is here.
// ===========================================================================
//
// ---------------------------------------------------------------------------
// 01  HAPPY PATH — setup done first                       -> 200 OK
//     Run  Create School  ->  Complete Provisioning  ->  this.
//     OUT: status: "ACTIVE"
//          activatedAt: <now>
//          firstActivation: true
//          subscriptionStatus: "NONE"
// ---------------------------------------------------------------------------
//
// ---------------------------------------------------------------------------
// 02  TOO EARLY — no roles yet                        -> 409 Conflict
//     Create a school and send this WITHOUT Complete Provisioning.
//     OUT: { "code": "SETUP_INCOMPLETE",
//            "message": "This school has no SCHOOL_ADMIN role. Run
//                        complete-provisioning first." }
//
//     Refused because a school with no SCHOOL_ADMIN role has nothing to attach
//     a first administrator to. Activating it produces a live school nobody
//     can log into.
// ---------------------------------------------------------------------------
//
// ---------------------------------------------------------------------------
// 03  TOO EARLY — a sequence is missing                -> 409 Conflict
//     Complete provisioning, then remove one row:
//
//       db.number_sequences.deleteOne({schoolId: "<id>", sequenceType: "FEE_INVOICE"})
//
//     OUT: { "code": "SETUP_INCOMPLETE",
//            "message": "This school has 46 of 47 number sequences. Run
//                        complete-provisioning first." }
//
//     The count is in the message on purpose — "incomplete" without a number
//     leaves you guessing what is missing.
// ---------------------------------------------------------------------------
//
// ---------------------------------------------------------------------------
// 04  SEND IT AGAIN — already live                     -> 409 Conflict
//     OUT: { "code": "SCHOOL_NOT_ACTIVATABLE",
//            "message": "A school at status ACTIVE cannot be activated. Only
//                        PROVISIONING can. A suspended school is
//                        reactivated, not activated." }
//
//     NOT idempotent, unlike Complete Provisioning. This one refuses, because
//     the caller believes they changed something and they did not. Bringing a
//     suspended school back is endpoint #5 reactivate — a different operation.
// ---------------------------------------------------------------------------
//
// ---------------------------------------------------------------------------
// 05  A SCHOOL ITS SUBSCRIPTION ALREADY ACTIVATED     -> 409 Conflict
//     Create School, Complete Provisioning, then Create Subscription — and
//     skip this endpoint. The school is ACTIVE already: a provisioned school
//     waiting only on a subscription is activated by the sale.
//     OUT: { "code": "SCHOOL_NOT_ACTIVATABLE" }, same as case 04.
//
//     There is no TRIAL starting state. A trial belongs to the SUBSCRIPTION,
//     where it has a plan and a period behind it.
// ---------------------------------------------------------------------------
//
// ---------------------------------------------------------------------------
// 06  CANCELLED SUBSCRIPTION                           -> 409 Conflict
//     Give the school a dead subscription first:
//
//       db.school_subscriptions.insertOne({
//         schoolId: "<id>", subscriptionNo: "SUB/T/1",
//         planDefinitionDocsId: "x", planVersion: 1,
//         status: "CANCELLED", billingCycle: "YEARLY",
//         autoRenew: false, current: true, recordState: "ACTIVE" })
//
//     OUT: { "code": "SUBSCRIPTION_NOT_ACTIVE",
//            "message": "The school's subscription is CANCELLED. It cannot be
//                        activated." }
//
//     Blocked for CANCELLED and EXPIRED only. ACTIVE, TRIAL, PAST_DUE and
//     SUSPENDED all pass — a school behind on payment is not a school that
//     should be shut out mid-term.
//
//     billingCycle must be MONTHLY | QUARTERLY | HALF_YEARLY | YEARLY | CUSTOM.
//     An invalid value written straight to MongoDB comes back as a 500, because
//     nothing validates enums on read.
// ---------------------------------------------------------------------------
//
// ---------------------------------------------------------------------------
// 07  NO SUBSCRIPTION AT ALL                           -> 200 OK
//     The ordinary case today. Activation is ALLOWED and says so:
//
//     OUT: subscriptionStatus: "NONE"
//          subscriptionNote: "No subscription exists for this school.
//                             Activation was allowed anyway because nothing
//                             creates subscriptions yet — this check must
//                             become a hard requirement once it does."
//
//     The plan says activation requires an active subscription. Nothing creates
//     one yet, so enforcing it strictly would make this endpoint unusable. The
//     response announces the gap rather than hiding it.
// ---------------------------------------------------------------------------
//
// ---------------------------------------------------------------------------
// 08  UNKNOWN SCHOOL ID                              -> 404 Not Found
//     Set {{schoolId}} to 6a90000000000000000000aa
//     OUT: { "code": "SCHOOL_NOT_FOUND" }
// ---------------------------------------------------------------------------

{
  "reason": "Non-payment. Third invoice unpaid past 60 days."
}

// ===========================================================================
//  TEST CASES  —  POST /platform/schools/{id}/suspend
//  Swap the body above for any block below, then Send.
//  {{schoolId}} must be an ACTIVE school — run Activate School first.
// ===========================================================================
//
// ---------------------------------------------------------------------------
// 01  SUSPEND AN ACTIVE SCHOOL                            -> 200 OK
//     The body above.
//     OUT: status: "SUSPENDED"
//          suspendedAt: <now>
//          statusReason: "Non-payment. Third invoice unpaid past 60 days."
//          activatedAt: <unchanged — still the original go-live date>
// ---------------------------------------------------------------------------
//
// ---------------------------------------------------------------------------
// 02  NO REASON                                       -> 400 Bad Request
//     OUT: { "code": "VALIDATION_FAILED",
//            "fieldErrors": { "reason": ["must not be blank"] } }
// {
// }
//
//     The reason is REQUIRED, unlike on reactivate. Suspension stops a whole
//     school, and one with no reason written down gets switched back on by the
//     next person who is asked about it.
// ---------------------------------------------------------------------------
//
// ---------------------------------------------------------------------------
// 03  BLANK REASON — same as missing                  -> 400 Bad Request
// {
//   "reason": "   "
// }
//     @NotBlank, not @NotNull. Whitespace does not count as an answer.
// ---------------------------------------------------------------------------
//
// ---------------------------------------------------------------------------
// 04  SCHOOL NOT ACTIVE YET                            -> 409 Conflict
//     Point {{schoolId}} at a school you have NOT activated.
//     OUT: { "code": "SCHOOL_NOT_SUSPENDABLE",
//            "message": "A school at status PROVISIONING cannot be suspended.
//                        Only ACTIVE can." }
//
//     Suspending a school that was never usable makes no sense.
// ---------------------------------------------------------------------------
//
// ---------------------------------------------------------------------------
// 05  SUSPEND TWICE                                    -> 409 Conflict
//     Send case 01 again.
//     OUT: { "code": "SCHOOL_NOT_SUSPENDABLE",
//            "message": "A school at status SUSPENDED cannot be suspended..." }
//
//     Not idempotent on purpose: the caller believes they changed something.
// ---------------------------------------------------------------------------
//
// ---------------------------------------------------------------------------
// 06  UNKNOWN SCHOOL ID                              -> 404 Not Found
//     Set {{schoolId}} to 6a90000000000000000000aa
//     OUT: { "code": "SCHOOL_NOT_FOUND" }
// ---------------------------------------------------------------------------
//
// ---------------------------------------------------------------------------
//  NOT DONE YET — worth knowing before you rely on this
//  Suspension does NOT revoke live sessions or stop scheduled jobs. Neither
//  service exists. A suspended school's users stay logged in until their
//  tokens expire, so this is a flag rather than a lock.
// ---------------------------------------------------------------------------

{
  "note": "Outstanding invoices cleared on 31 August."
}

// ===========================================================================
//  TEST CASES  —  POST /platform/schools/{id}/reactivate
//  {{schoolId}} must be a SUSPENDED school.
// ===========================================================================
//
// ---------------------------------------------------------------------------
// 01  REACTIVATE WITH A NOTE                              -> 200 OK
//     The body above. The note REPLACES the stored statusReason.
//     OUT: status: "ACTIVE"
//          statusReason: "Outstanding invoices cleared on 31 August."
// ---------------------------------------------------------------------------
//
// ---------------------------------------------------------------------------
// 02  REACTIVATE WITH NO BODY AT ALL                      -> 200 OK
//     Delete the whole body. The endpoint accepts an absent body.
//     OUT: status: "ACTIVE"
//          statusReason: <the suspension reason, KEPT>
//          suspendedAt:  <KEPT — the most recent suspension>
//          activatedAt:  <unchanged — the original go-live date>
//
//     The note is OPTIONAL here, unlike the reason on suspend. Letting a school
//     back in usually means the problem was settled; forcing a sentence there
//     produces "resolved" typed a hundred times, which looks like a record and
//     is not.
// ---------------------------------------------------------------------------
//
// ---------------------------------------------------------------------------
// 03  WHAT IS DELIBERATELY *NOT* RESET                    -> 200 OK
//     Run case 02 and read the response carefully:
//
//       activatedAt  NOT re-stamped  — a school suspended in June and brought
//                                      back in July keeps its April go-live date
//       suspendedAt  NOT cleared     — it is the MOST RECENT suspension, and
//                                      keeping it is how you see this school has
//                                      been suspended before
//       statusReason NOT cleared     — unless a note is sent
//
//     All three are history, not current state.
// ---------------------------------------------------------------------------
//
// ---------------------------------------------------------------------------
// 04  SCHOOL IS ALREADY ACTIVE                         -> 409 Conflict
//     OUT: { "code": "SCHOOL_NOT_REACTIVATABLE",
//            "message": "A school at status ACTIVE cannot be reactivated. Only
//                        SUSPENDED can. A school that has never gone live is
//                        activated, not reactivated." }
// ---------------------------------------------------------------------------
//
// ---------------------------------------------------------------------------
// 05  SCHOOL NEVER WENT LIVE                           -> 409 Conflict
//     Point {{schoolId}} at a PROVISIONING school.
//     OUT: { "code": "SCHOOL_NOT_REACTIVATABLE" }
//
//     Use  Activate School  for a school that has never been live. Reactivate is
//     only for bringing a suspended one back.
// ---------------------------------------------------------------------------
//
// ---------------------------------------------------------------------------
// 06  UNKNOWN SCHOOL ID                              -> 404 Not Found
//     Set {{schoolId}} to 6a90000000000000000000aa
//     OUT: { "code": "SCHOOL_NOT_FOUND" }
// ---------------------------------------------------------------------------
//
// ---------------------------------------------------------------------------
//  NOTE — activate vs reactivate
//  Reactivate does NOT re-run the setup and subscription checks that guard
//  Activate School. A suspended school was already live once, so it passed
//  them. Re-running them would mean a school suspended for non-payment could
//  never be let back in as a goodwill gesture, which is what this is for.
// ---------------------------------------------------------------------------

{
  "currentSubdomain": "{{createdSubdomain}}",
  "newSubdomain": "orbit-astra-renamed-{{$timestamp}}"
}

// ===========================================================================
//  TEST CASES  —  PATCH /platform/schools/{id}/subdomain
//  Platform surface. Needs {{schoolId}} — run Create School first.
// ===========================================================================
//
//  THE SUBDOMAIN IS THE KEY THAT RESOLVES A REQUEST TO A TENANT. This is not a
//  profile edit; it moves the school's address. That is why it is here and not
//  on #6, which has no field for it.
//
//  currentSubdomain MUST MATCH what the school answers to today. Nothing reads
//  the value — it exists so the one endpoint that can take a tenant off the
//  air cannot be aimed at the wrong one by a mis-pasted id. It is the only
//  confirmation field in this package.
//
//  THE OLD LABEL IS RELEASED IMMEDIATELY. Nothing reserves it, nothing
//  redirects, and the school is NOT told. Every bookmark, saved link and
//  stored login pointing at the old label is dead the moment this returns, and
//  the next school to ask can claim it.
//
//  AFTER RUNNING THIS, {{createdSubdomain}} IS STALE. The tests below update
//  it, so the school-surface requests keep working. If you run this by hand,
//  fix the variable or every /schools/current request starts 404ing.
//
// ---------------------------------------------------------------------------
// 01  CHANGE THE SUBDOMAIN                                 -> 200 OK
//     The body above.
//     OUT: previousSubdomain: the old one, subdomain: the new one
//          nextStep: "Every link, bookmark and saved login using '...' is now
//                     dead — nothing redirects, and the school has NOT been
//                     told. '...' is now free for any school to claim."
// ---------------------------------------------------------------------------
//
// 02  WRONG CONFIRMATION                              -> 409 Conflict
// {
//   "currentSubdomain": "not-this-school",
//   "newSubdomain": "anything-else"
// }
//     OUT: { "code": "SUBDOMAIN_CONFIRMATION_MISMATCH",
//            "message": "This school answers to '...', not '...'." }
//     THE GUARD THAT MATTERS MOST HERE.
// ---------------------------------------------------------------------------
//
// 03  SAME AS THE CURRENT ONE                         -> 409 Conflict
//     Set newSubdomain equal to currentSubdomain.
//     OUT: { "code": "SUBDOMAIN_UNCHANGED" }
// ---------------------------------------------------------------------------
//
// 04  A RESERVED WORD                                 -> 409 Conflict
// {
//   "currentSubdomain": "{{createdSubdomain}}",
//   "newSubdomain": "login"
// }
//     OUT: { "code": "SUBDOMAIN_RESERVED" }
//     A school on 'login' or 'api' would receive traffic and credentials meant
//     for the platform. Same list #1 uses — one list, not two to keep in step.
// ---------------------------------------------------------------------------
//
// 05  A BAD SHAPE                                     -> 409 Conflict
// {
//   "currentSubdomain": "{{createdSubdomain}}",
//   "newSubdomain": "-bad-"
// }
//     OUT: { "code": "SUBDOMAIN_INVALID" }
//     No leading or trailing hyphen; lowercase letters, digits, inner hyphens.
// ---------------------------------------------------------------------------
//
// 06  ALREADY IN USE                                  -> 409 Conflict
//     Create a second school, then send its subdomain here.
//     OUT: { "code": "SUBDOMAIN_TAKEN" }
// ---------------------------------------------------------------------------
//
// 07  NO CONFIRMATION FIELD                          -> 400 Bad Request
// {
//   "newSubdomain": "orbit-astra-2"
// }
//     OUT: fieldErrors: { "currentSubdomain": "must not be blank" }
//     400, not 409 — the request is malformed, not refused.
// ---------------------------------------------------------------------------
//
// 08  UNKNOWN SCHOOL ID                                -> 404 Not Found
//     OUT: { "code": "SCHOOL_NOT_FOUND" }
// ---------------------------------------------------------------------------
//
// 09  A SCHOOL BEING DELETED                          -> 409 Conflict
//     Only reachable once #15 to #17 exist.
//     OUT: { "code": "SCHOOL_NOT_EDITABLE" }
// ---------------------------------------------------------------------------

{
  "name": "Premium",
  "description": "Advanced ERP modules and AI capabilities for growing schools.",
  "billingCycle": "YEARLY",
  "listPrice": 49999,
  "currencyCode": "INR",
  "maxStudents": 2000,
  "maxUsers": 250
}

// ===========================================================================
//  TEST CASES  —  POST /platform/plans/drafts
//  Platform surface. No tenant header: a PlanDefinition has no schoolId.
// ===========================================================================
//
//  THIS IS THE PLATFORM'S OWN PRICE LIST, NOT SCHOOL FEES. Money a school pays
//  us for Orbit Sphere. models/finance is the other thing entirely — money a
//  parent pays a school — and nothing here may touch a FeeInvoice.
//
//  YOU DO NOT SEND planCode. It is worked out from the name — "Premium Plus"
//  becomes PREMIUM_PLUS — so a create form asks for one thing instead of
//  making somebody type the same words twice in two shapes. Send one only when
//  the derived code will not do (case 03).
//
//  WHY THE CODE EXISTS AT ALL, given the name is right there: it is the FAMILY
//  KEY, the only thing joining version 1, 2 and 3 of one plan. A subscription
//  stores a document id and a version number, so without it "version 2" means
//  version 2 of nothing, and #5 (copy a published plan into a new version) has
//  no way to say which family the copy joins. The name cannot do that job,
//  because a name is display text somebody will want to change — and a key
//  that can change is not a key.
//
//  IT ALWAYS MAKES A DRAFT. status, planVersion and publiclyAvailable are NOT
//  on the request:
//    status             always DRAFT   — nobody can buy it while we are still
//                                        deciding the price
//    planVersion        always 1       — later versions come from #5, which
//                                        copies a published one
//    publiclyAvailable  always false   — #7 decides if it shows publicly
//  Send them anyway and they are ignored, not half-honoured (case 10).
//
//  FEATURES ARE NOT ACCEPTED HERE. The plan starts with an empty feature list
//  and #3 sets the whole list in one go — the same shape academic years use
//  for holidays. A create that can fail on either a bad price or a bad feature
//  leaves you working out which, and a half-filled feature list is the "plan
//  nobody can price" that #3 exists to prevent.
//
//  WHY /drafts IS IN THE PATH: so nobody reads POST /platform/plans and thinks
//  they are putting a plan on sale. Every endpoint after this addresses the
//  plan by code and version — /platform/plans/PREMIUM/versions/1 — because
//  from then on draft-ness is a status on a plan that exists.
//
// ---------------------------------------------------------------------------
// 01  CREATE A DRAFT PLAN                                  -> 201 Created
//     The body above.
//     OUT: status: "DRAFT", planVersion: 1, publiclyAvailable: false,
//          featureCount: 0, sellable: false
//     Header: Location: /platform/plans/PREMIUM/versions/1
//
//     sellable is DERIVED, never stored: published AND public AND inside the
//     selling window. Three separate facts, so every screen does not combine
//     them slightly differently.
// ---------------------------------------------------------------------------
//
// 02  THE CODE COMES FROM THE NAME                         -> 201 Created
// {
//   "name": "   Premium Plus   ",
//   "description": "   ",
//   "billingCycle": "YEARLY",
//   "listPrice": 79999,
//   "currencyCode": "inr",
//   "maxStudents": 5000,
//   "maxUsers": 500
// }
//     OUT: planCode "PREMIUM_PLUS"  <- derived; nothing was sent
//          name      "Premium Plus" <- trimmed
//          description null         <- "   " is nothing, so it is nothing
//          listPrice 79999.00       <- always two decimal places
//          currencyCode "INR"       <- uppercased
//
//     Anything that is not a letter or digit becomes one underscore, and the
//     ends are trimmed:
//        "Premium Plus"     -> PREMIUM_PLUS
//        "Starter (2026)"   -> STARTER_2026
//        "Schools & Trusts" -> SCHOOLS_TRUSTS
// ---------------------------------------------------------------------------
//
// 02b AN EXPLICIT CODE STILL WINS                          -> 201 Created
// {
//   "name": "Anything",
//   "planCode": "enterprise",
//   "billingCycle": "YEARLY",
//   "listPrice": 9,
//   "currencyCode": "INR",
//   "maxStudents": 10,
//   "maxUsers": 10
// }
//     OUT: planCode "ENTERPRISE" — uppercased, hyphens become underscores.
//     For when the derived code is taken, or has to match something outside
//     this system.
// ---------------------------------------------------------------------------
//
// 02c A NAME THAT CANNOT PRODUCE A CODE               -> 409 Conflict
// {
//   "name": "★★★", "billingCycle": "YEARLY", "listPrice": 1,
//   "currencyCode": "INR", "maxStudents": 1, "maxUsers": 1
// }
//     OUT: { "code": "PLAN_CODE_INVALID",
//            "message": "No plan code could be worked out from the name '★★★'.
//                        Send a planCode of letters, digits and inner
//                        underscores." }
//     The message names the NAME, not a code the caller never sent.
// ---------------------------------------------------------------------------
//
// 03  A NAME THAT DERIVES A CODE SOMEBODY HAS         -> 409 Conflict
//     Send case 01 twice. Two plans both called "Premium" derive the same
//     PREMIUM code, and casing does not help — "premium" normalizes to it too.
//     OUT: { "code": "PLAN_CODE_TAKEN",
//            "message": "A plan called 'PREMIUM' already exists. To change its
//                        price, make a new version of it instead of a new
//                        plan." }
//
//     Refused even though the unique index is on planCode AND planVersion, so
//     a second PREMIUM v1 would technically fit. planCode is the plan's
//     permanent identity and SchoolSubscription stores it — two plans sharing
//     it could never be told apart, and "which PREMIUM" would have no answer.
// ---------------------------------------------------------------------------
//
// 04  A FREE PLAN                                          -> 201 Created
// {
//   "planCode": "FREE",
//   "name": "Free",
//   "billingCycle": "MONTHLY",
//   "listPrice": 0,
//   "currencyCode": "INR",
//   "maxStudents": 50,
//   "maxUsers": 5
// }
//     ZERO IS ALLOWED. A free tier is a real plan.
// ---------------------------------------------------------------------------
//
// 05  A NEGATIVE PRICE                               -> 400 Bad Request
// {
//   "planCode": "ODD", "name": "Odd", "billingCycle": "MONTHLY",
//   "listPrice": -5, "currencyCode": "INR", "maxStudents": 10, "maxUsers": 5
// }
//     OUT: { "code": "PRICE_NEGATIVE" }
//     A plan we pay the school to be on is not a thing.
// ---------------------------------------------------------------------------
//
// 06  MORE THAN TWO DECIMAL PLACES                   -> 400 Bad Request
// {
//   "planCode": "ODD2", "name": "Odd", "billingCycle": "MONTHLY",
//   "listPrice": 1999.999, "currencyCode": "INR", "maxStudents": 10,
//   "maxUsers": 5
// }
//     OUT: { "code": "PRICE_TOO_PRECISE" }
//     REFUSED, NOT ROUNDED. Rounding somebody's price for them is how 1999.999
//     quietly becomes 2000.00 on every invoice for a year.
// ---------------------------------------------------------------------------
//
// 07  A CURRENCY THAT DOES NOT EXIST                   -> 409 Conflict
// {
//   "planCode": "ODD3", "name": "Odd", "billingCycle": "MONTHLY",
//   "listPrice": 1, "currencyCode": "RUP", "maxStudents": 10, "maxUsers": 5
// }
//     OUT: { "code": "CURRENCY_INVALID",
//            "message": "'RUP' is not an ISO 4217 currency code. Example:
//                        INR." }
//     Checked against the JDK's ISO 4217 list, not a hand-written one — for
//     the same reason time zones are. RUP and INS look plausible and do not
//     exist, and nobody notices until an invoice is issued in one.
//
//     409 rather than 400: the request is well formed and still refused.
// ---------------------------------------------------------------------------
//
// 08  A LIMIT OF ZERO                                -> 400 Bad Request
// {
//   "planCode": "ODD4", "name": "Odd", "billingCycle": "MONTHLY",
//   "listPrice": 1, "currencyCode": "INR", "maxStudents": 0, "maxUsers": 5
// }
//     OUT: { "code": "LIMIT_TOO_LOW" }
//     A plan capped at zero students blocks the first thing the school tries
//     to do, which reads as a broken platform rather than as the plan it was
//     sold.
// ---------------------------------------------------------------------------
//
// 09  A SELLING WINDOW THAT RUNS BACKWARDS           -> 400 Bad Request
// {
//   "planCode": "ODD5", "name": "Odd", "billingCycle": "YEARLY",
//   "listPrice": 1, "currencyCode": "INR", "maxStudents": 10, "maxUsers": 5,
//   "effectiveFrom": "2027-04-01T00:00:00Z",
//   "effectiveUntil": "2026-04-01T00:00:00Z"
// }
//     OUT: { "code": "INVALID_SELLING_WINDOW" }
//     Both dates are OPTIONAL, and a draft usually has neither — #4 stamps
//     effectiveFrom when it publishes. Only the pair together can be wrong.
// ---------------------------------------------------------------------------
//
// 10  FIELDS THAT ARE NOT OURS TO SET                      -> 201 Created
// {
//   "planCode": "IGNORED",
//   "name": "Try to cheat",
//   "billingCycle": "YEARLY",
//   "listPrice": 1,
//   "currencyCode": "INR",
//   "maxStudents": 10,
//   "maxUsers": 5,
//   "status": "ACTIVE",
//   "planVersion": 9,
//   "publiclyAvailable": true,
//   "features": [{ "featureCode": "EVERYTHING" }]
// }
//     OUT: status "DRAFT", planVersion 1, publiclyAvailable false,
//          featureCount 0 — every one of those four was ignored.
//     They are not on the request record, so Jackson drops them. A plan that
//     could be created ACTIVE would be on sale before it was priced.
// ---------------------------------------------------------------------------
//
// 11  AN EXPLICIT CODE THAT IS NOT A CODE             -> 409 Conflict
// {
//   "planCode": "_bad_", "name": "X", "billingCycle": "MONTHLY",
//   "listPrice": 1, "currencyCode": "INR", "maxStudents": 10, "maxUsers": 5
// }
//     OUT: { "code": "PLAN_CODE_INVALID" }
//     Letters, digits and INNER underscores. No leading or trailing one — and
//     a derived code never has one, because the ends are trimmed.
// ---------------------------------------------------------------------------
//
// 12  A BILLING CYCLE THAT DOES NOT EXIST            -> 400 Bad Request
//     "billingCycle": "WEEKLY"
//     OUT: { "code": "MALFORMED_REQUEST" }
//     Accepted: MONTHLY, QUARTERLY, HALF_YEARLY, YEARLY, CUSTOM.
// ---------------------------------------------------------------------------
//
// 13  NOTHING AT ALL                                 -> 400 Bad Request
// {
// }
//     OUT: { "code": "VALIDATION_FAILED" } with fieldErrors naming name,
//     billingCycle, listPrice, currencyCode, maxStudents, maxUsers.
//     NOT planCode — it is optional, and with no name there is nothing to
//     derive it from either.
// ---------------------------------------------------------------------------

{
  "name": "Premium Plus",
  "listPrice": 44999,
  "maxStudents": 3000
}

// ===========================================================================
//  TEST CASES  —  PATCH /platform/plans/{code}/versions/{version}
//  Platform surface. Run Create Plan Draft first — it saves {{planCode}}.
// ===========================================================================
//
//  ONLY A DRAFT CAN BE EDITED. That is the rule the whole catalogue is built
//  on. The moment a plan is published a school can be on it, and changing the
//  price then would change what they agreed to pay — retroactively, with no
//  record that it happened. #5 copies a published version into a new draft
//  instead, and the schools on the old version stay where they are.
//
//  PARTIAL, the same way core's PATCHes are:
//     omitted or null -> leave it exactly as it is
//     ""              -> clear it (description only)
//     a value         -> replace it
//  name cannot be cleared: "" is a 400, not a deletion.
//
//  THE SELLING WINDOW IS REPLACED AS A PAIR, not as two loose fields. The two
//  dates are only meaningful next to each other — an effectiveUntil moved
//  earlier than the existing effectiveFrom is a plan that can never be sold —
//  so changing one alone could create a window nobody asked for. Same
//  reasoning that puts the school's address behind a PUT.
//
//  NOT ON THIS REQUEST: planCode and planVersion (they are the identity, in
//  the URL), status (publish is #4, retire is #6), publiclyAvailable (#7) and
//  features (#3). Each is a decision with its own rules; a PATCH that could
//  set them all would make "put this on sale" look like "fix a typo".
//
// ---------------------------------------------------------------------------
// 01  CHANGE A FEW FIELDS                                  -> 200 OK
//     The body above. Everything not mentioned is untouched.
//     OUT: status still "DRAFT", planVersion still 1.
// ---------------------------------------------------------------------------
//
// 02  CHANGE ONE FIELD ONLY                                -> 200 OK
// {
//   "name": "   Renamed   "
// }
//     Trimmed on the way in. Price, currency, cycle and limits unchanged.
// ---------------------------------------------------------------------------
//
// 03  CLEAR THE DESCRIPTION                                -> 200 OK
// {
//   "description": ""
// }
//     OUT: description null. Omitting it instead would have left it alone.
// ---------------------------------------------------------------------------
//
// 04  REPLACE THE SELLING WINDOW                           -> 200 OK
// {
//   "sellingWindow": {
//     "effectiveFrom": "2026-06-01T00:00:00Z",
//     "effectiveUntil": "2027-05-31T00:00:00Z"
//   }
// }
// ---------------------------------------------------------------------------
//
// 05  CLEAR THE SELLING WINDOW                             -> 200 OK
// {
//   "sellingWindow": { "effectiveFrom": null, "effectiveUntil": null }
// }
//     Nulls INSIDE the pair mean "no date". This is the only way to clear a
//     date here — "" cannot mean anything to an instant.
//     OMITTING sellingWindow leaves the window alone. The two are different.
// ---------------------------------------------------------------------------
//
// 06  EDIT A PUBLISHED PLAN                            -> 409 Conflict
//     Publish it with #4 first, then send anything.
//     OUT: { "code": "PLAN_NOT_EDITABLE",
//            "message": "'PREMIUM' version 1 is ACTIVE and cannot be edited.
//                        Schools may already be on it. Make a new version of
//                        it instead." }
//     A RETIRED plan is refused the same way — schools may still be on it.
//     THIS IS THE POINT OF THE ENDPOINT. Nothing is changed by a refusal.
// ---------------------------------------------------------------------------
//
// 07  AN EMPTY BODY                                  -> 400 Bad Request
// {
// }
//     OUT: { "code": "NOTHING_TO_UPDATE" }
//     Checked BEFORE the plan is looked up, so an empty PATCH on a plan that
//     does not exist says the body is empty rather than sending you hunting
//     for a missing plan.
// ---------------------------------------------------------------------------
//
// 08  TRY TO CLEAR THE NAME                          -> 400 Bad Request
// {
//   "name": "   "
// }
//     OUT: { "code": "PLAN_NAME_REQUIRED" }
// ---------------------------------------------------------------------------
//
// 09  A BAD PRICE, CURRENCY OR LIMIT                 -> 400 / 409
//     { "listPrice": -1 }      -> 400 PRICE_NEGATIVE
//     { "listPrice": 9.999 }   -> 400 PRICE_TOO_PRECISE
//     { "currencyCode": "RUP" }-> 409 CURRENCY_INVALID
//     { "maxUsers": 0 }        -> 400 LIMIT_TOO_LOW
//     The same checks #1 makes, from the same validator — one set of rules,
//     not two that drift.
// ---------------------------------------------------------------------------
//
// 10  A WINDOW THAT RUNS BACKWARDS                   -> 400 Bad Request
// {
//   "sellingWindow": {
//     "effectiveFrom": "2027-01-01T00:00:00Z",
//     "effectiveUntil": "2026-01-01T00:00:00Z"
//   }
// }
//     OUT: { "code": "INVALID_SELLING_WINDOW" }
// ---------------------------------------------------------------------------
//
// 11  A PLAN OR VERSION THAT DOES NOT EXIST            -> 404 Not Found
//     Change the URL to /platform/plans/NOPE/versions/1, or ask for version 9.
//     OUT: { "code": "PLAN_NOT_FOUND",
//            "message": "No plan 'NOPE' version 1 exists." }
// ---------------------------------------------------------------------------
//
// 12  A LOWERCASE CODE IN THE URL                          -> 200 OK
//     /platform/plans/premium_plus/versions/1 finds PREMIUM_PLUS.
//     A code arrives in a URL where a person may have typed it, so it is
//     normalized the same way it was when the plan was created. A code of the
//     wrong shape simply matches nothing — that is a 404, not a complaint
//     about its shape.
// ---------------------------------------------------------------------------
//
// 13  FIELDS THAT ARE NOT OURS TO SET                      -> 200 OK
// {
//   "name": "Fine",
//   "planCode": "HACKED",
//   "planVersion": 9,
//   "status": "ACTIVE",
//   "publiclyAvailable": true
// }
//     OUT: planCode, planVersion, status and publiclyAvailable all unchanged.
//     They are not on the request record, so Jackson drops them.
// ---------------------------------------------------------------------------

{
  "features": [
    { "featureCode": "STUDENT_MANAGEMENT", "usageLimit": 2000, "overagePolicy": "WARN" },
    { "featureCode": "ATTENDANCE" },
    { "featureCode": "EXAMINATIONS" },
    { "featureCode": "TRANSPORT", "usageLimit": 12 },
    { "featureCode": "HOSTEL", "enabled": false }
  ]
}

// ===========================================================================
//  TEST CASES  —  PUT /platform/plans/{code}/versions/{version}/features
//  Platform surface. Run Create Plan Draft first — it saves {{planCode}}.
// ===========================================================================
//
//  featureCode IS A FIXED LIST, not free text. Changed on 2026-09-03: it was a
//  String, which accepted "STUDNET_MANAGEMENT" with a 200 — the plan looked
//  perfect on every screen while the feature access service, asking for
//  STUDENT_MANAGEMENT, found nothing and locked the school out of what they
//  had paid for. One transposed letter, discovered when they rang up.
//
//  A feature code points at behaviour in our code, not at anything a user
//  invents, so the set is closed. An unknown value is now a 400 that lists
//  every accepted one (case 05).
//
//  THE 24 FEATURES:
//    Teaching   STUDENT_MANAGEMENT · ACADEMICS · ATTENDANCE · TIMETABLE
//               EXAMINATIONS · HOMEWORK
//    Money      FEE_MANAGEMENT · PAYROLL
//    People     STAFF_MANAGEMENT · ADMISSIONS_CRM
//    Daily      TRANSPORT · LIBRARY · HOSTEL · MESS · HEALTH · FRONT_OFFICE
//    Premises   INVENTORY · PROCUREMENT · FACILITIES
//    Comms      NOTIFICATIONS · DOCUMENTS · GALLERY · FEEDBACK · STUDENT_LIFE
//
//  YOU DO NOT SEND usageMetric. Each feature declares what it is measured in,
//  so the metric is copied from the feature. TRANSPORT is counted in VEHICLES,
//  STUDENT_MANAGEMENT in ACTIVE_STUDENTS. "Student management limited to 2000
//  gigabytes" is not refused — it cannot be written down (case 08).
//
//  SOME FEATURES HAVE NOTHING TO COUNT. ATTENDANCE is included or it is not,
//  so a usageLimit on it is refused (case 06). Every response says which
//  metric applies, or null.
//
//  THE WHOLE LIST, NOT ONE FEATURE AT A TIME. A feature list is priced as a
//  set — "2000 students and examinations for this much" is one offer — and
//  there is no moment at which half of it is a plan.
//
//  ONLY A DRAFT. Features are what a school is buying; changing them on a
//  published plan changes what somebody already bought.
//
//  DEFAULTS: enabled true, overagePolicy BLOCK.
//
// ---------------------------------------------------------------------------
// 01  SET FIVE FEATURES                                    -> 200 OK
//     The body above.
//     OUT: featureCount 5, changeSummary "0 out, 5 in", and every row carries
//          its label and description from the enum:
//            STUDENT_MANAGEMENT "Student management"
//              limit 2000 ACTIVE_STUDENTS, policy WARN
//            ATTENDANCE         "Attendance"        limit null, metric null
//            TRANSPORT          "Transport"         limit 12 VEHICLES
//            HOSTEL             "Hostel"            enabled false
//
//     label and description come from FeatureCode, the only place they are
//     written — so the pricing page, the comparison table and the "your plan
//     does not include this" message all say the same words.
// ---------------------------------------------------------------------------
//
// 02  REPLACE WITH A SHORTER LIST                          -> 200 OK
// {
//   "features": [
//     { "featureCode": "STUDENT_MANAGEMENT", "usageLimit": 500 }
//   ]
// }
//     The four not listed are gone. That is what replace means.
// ---------------------------------------------------------------------------
//
// 03  EMPTY THE LIST                                       -> 200 OK
// {
//   "features": []
// }
//     The honest way to clear it, and why there is no separate delete.
//     A body of {} is a 400 — features is required, and forgetting a field
//     should not wipe a plan's feature access.
// ---------------------------------------------------------------------------
//
// 04  THE SAME FEATURE TWICE                         -> 400 Bad Request
// {
//   "features": [{ "featureCode": "LIBRARY" }, { "featureCode": "LIBRARY" }]
// }
//     OUT: { "code": "DUPLICATE_FEATURE" }
//     Two rows for one feature is not a bigger feature access, it is a question:
//     which of the two limits applies?
// ---------------------------------------------------------------------------
//
// 05  A MISSPELLED FEATURE                           -> 400 Bad Request
// {
//   "features": [
//     { "featureCode": "STUDENT_MANAGEMENT" },
//     { "featureCode": "STUDNET_MANAGEMENT" }
//   ]
// }
//     OUT: { "code": "INVALID_VALUE",
//            "message": "'STUDNET_MANAGEMENT' is not a valid value for
//                        'features[1].featureCode'. Accepted values:
//                        STUDENT_MANAGEMENT, ACADEMICS, ATTENDANCE, ..." }
//     THE ROW IS NAMED AND THE OPTIONS ARE LISTED. This is the whole reason
//     featureCode stopped being a String. Nothing is written.
// ---------------------------------------------------------------------------
//
// 06  A LIMIT ON SOMETHING WITH NOTHING TO COUNT     -> 400 Bad Request
// {
//   "features": [{ "featureCode": "ATTENDANCE", "usageLimit": 500 }]
// }
//     OUT: { "code": "FEATURE_NOT_MEASURABLE",
//            "message": "'ATTENDANCE' has no limit to set — it is either
//                        included or it is not. Drop usageLimit, or use
//                        \"enabled\": false to exclude it." }
//     A plan that reads as capped and behaves as unlimited is worse than one
//     with no cap at all.
//
//     MEASURABLE:   STUDENT_MANAGEMENT (ACTIVE_STUDENTS) · PAYROLL and
//     STAFF_MANAGEMENT (ACTIVE_STAFF) · TRANSPORT (VEHICLES) · LIBRARY
//     (LIBRARY_TITLES) · HOSTEL (HOSTEL_BEDS) · NOTIFICATIONS (SMS_MESSAGES) ·
//     DOCUMENTS and GALLERY (STORAGE_MEGABYTES)
//     NOT MEASURABLE: everything else — included or not.
// ---------------------------------------------------------------------------
//
// 07  ENABLED WITH A LIMIT OF ZERO                   -> 400 Bad Request
// {
//   "features": [{ "featureCode": "TRANSPORT", "usageLimit": 0 }]
// }
//     OUT: { "code": "FEATURE_LIMIT_ZERO" }
//     "Included, but you may use none of it" is the same outcome as switching
//     it off, by a route that leaves it listed as available. Send
//     "enabled": false — which IS allowed with a limit of 0.
//     A negative limit is FEATURE_LIMIT_NEGATIVE.
// ---------------------------------------------------------------------------
//
// 08  TRY TO CHOOSE THE METRIC                             -> 200 OK
// {
//   "features": [
//     { "featureCode": "STUDENT_MANAGEMENT", "usageLimit": 2000,
//       "usageMetric": "STORAGE_MEGABYTES" }
//   ]
// }
//     OUT: usageMetric "ACTIVE_STUDENTS" — the field is not on the request, so
//     it is ignored and the feature's own metric is used.
//
//     IT IS STORED, NOT LOOKED UP ON READ. A plan version is immutable once
//     published: if TRANSPORT were ever changed from VEHICLES to ROUTES, a
//     plan sold last year must keep meaning 12 vehicles.
// ---------------------------------------------------------------------------
//
// 09  A BAD OVERAGE POLICY                           -> 400 Bad Request
// {
//   "features": [{ "featureCode": "LIBRARY", "overagePolicy": "SHRUG" }]
// }
//     OUT: { "code": "INVALID_VALUE",
//            "message": "'SHRUG' is not a valid value for
//                        'features[0].overagePolicy'. Accepted values: BLOCK,
//                        WARN, ALLOW, CHARGE." }
// ---------------------------------------------------------------------------
//
// 10  NO featureCode AT ALL                          -> 400 Bad Request
// {
//   "features": [{ "usageLimit": 5 }]
// }
//     OUT: fieldErrors: { "features[0].featureCode": ["must not be null"] }
// ---------------------------------------------------------------------------
//
// 11  ON A PUBLISHED PLAN                              -> 409 Conflict
//     Publish it with #4 first.
//     OUT: { "code": "PLAN_NOT_EDITABLE",
//            "message": "... is ACTIVE and its features cannot be changed." }
//     Not reachable from Postman yet — #4 is not built.
// ---------------------------------------------------------------------------
//
// 12  A PLAN THAT DOES NOT EXIST                       -> 404 Not Found
//     OUT: { "code": "PLAN_NOT_FOUND" }
// ---------------------------------------------------------------------------

{
}

// ===========================================================================
//  TEST CASES  —  POST /platform/plans/{code}/versions/{version}/publish
//  Platform surface. No body needed; anything sent is ignored.
// ===========================================================================
//
//  THIS IS A ONE-WAY DOOR. From here the version can NEVER be edited again:
//  #2 (details) and #3 (features) both refuse anything that is not a DRAFT,
//  and there is no unpublish. A school can be on it from the moment it goes
//  live, and changing what they bought after they bought it is the thing this
//  whole group is arranged to prevent.
//
//  To change the price afterwards: #5, a new version. The schools on this
//  version stay exactly where they are.
//
//  BECAUSE IT CANNOT BE UNDONE, IT IS CHECKED RATHER THAN TRUSTED. Two things
//  are refused here rather than discovered by a school:
//    - a plan with no features would take their money and grant nothing
//    - a plan whose selling window has already closed could never be bought
//
//  PUBLISHING DOES NOT PUT IT ON THE PUBLIC LIST. That is #7. A published plan
//  is real and can be offered privately in a quote; whether it shows on the
//  pricing page is a separate decision, so it is a separate endpoint. Expect
//  sellable: false straight after publishing.
//
// ---------------------------------------------------------------------------
// 01  PUBLISH A COMPLETE DRAFT                             -> 200 OK
//     Run Create Plan Draft, then Set Plan Features, then this.
//     OUT: status "ACTIVE", effectiveFrom stamped with now,
//          publiclyAvailable false, sellable false
//          nextStep: "Published, and now permanent: this version can never be
//                     edited again. It is NOT on the public list yet ..."
// ---------------------------------------------------------------------------
//
// 02  A DRAFT WITH NO FEATURES                         -> 409 Conflict
//     Create a draft and publish it without running Set Plan Features.
//     OUT: { "code": "PLAN_HAS_NO_FEATURES",
//            "message": "... has no features, so a school buying it would get
//                        nothing. Set its features first." }
// ---------------------------------------------------------------------------
//
// 03  PUBLISH IT AGAIN                                 -> 409 Conflict
//     OUT: { "code": "PLAN_ALREADY_PUBLISHED",
//            "message": "... is already published. To change it, make a new
//                        version." }
//     NOT an idempotent 200. "It was already published" and "you just
//     published it" are different facts, and a caller who cannot tell them
//     apart will assume the wrong one — on the one action that cannot be
//     undone.
// ---------------------------------------------------------------------------
//
// 04  A SELLING WINDOW THAT HAS ALREADY CLOSED        -> 409 Conflict
//     On a draft, set the window in the past with #2:
//       { "sellingWindow": { "effectiveFrom": "2020-01-01T00:00:00Z",
//                            "effectiveUntil": "2021-01-01T00:00:00Z" } }
//     then publish.
//     OUT: { "code": "PLAN_WINDOW_ALREADY_CLOSED",
//            "message": "... stops being sold on Friday 1 January 2021
//                        12:00AM, which has passed." }
//     EVERY DATE IN A MESSAGE IS SPELLED OUT — "Friday 1 January 2021
//     12:00AM", not 2021-01-01T00:00:00Z. A plan's selling window belongs
//     to the platform rather than to any school, so it reads in UTC; a date
//     that belongs to a school reads in that school's own timezone.
// ---------------------------------------------------------------------------
//
// 05  A LAUNCH DATE IN THE FUTURE                          -> 200 OK
//     On a draft, set effectiveFrom to a future date with #2, then publish.
//     OUT: status "ACTIVE", effectiveFrom UNCHANGED — the date chosen while it
//          was a draft still stands; publishing only fills an empty one.
//          sellable false, because the window has not opened.
//          nextStep says "It goes on sale on Thursday 1 April 2027 12:00AM."
// ---------------------------------------------------------------------------
//
// 06  AFTERWARDS, IT IS FROZEN                         -> 409 Conflict
//     PATCH the details:  409 PLAN_NOT_EDITABLE
//       "... is ACTIVE and cannot be edited."
//     PUT the features:   409 PLAN_NOT_EDITABLE
//       "... is ACTIVE and its features cannot be changed."
//     THIS IS THE POINT OF THE ENDPOINT. Check both after case 01.
// ---------------------------------------------------------------------------
//
// 07  A RETIRED PLAN                                   -> 409 Conflict
//     Retire it with #6 first (not built yet).
//     OUT: { "code": "PLAN_NOT_EDITABLE" } — "... is RETIRED and cannot be
//     published." Retiring is not a way back to draft.
// ---------------------------------------------------------------------------
//
// 08  A PLAN OR VERSION THAT DOES NOT EXIST             -> 404 Not Found
//     OUT: { "code": "PLAN_NOT_FOUND" }
// ---------------------------------------------------------------------------

{
  "publiclyAvailable": true
}

// ===========================================================================
//  TEST CASES  —  PATCH /platform/plans/{code}/versions/{version}/availability
//  Platform surface.
// ===========================================================================
//
//  PUBLIC LIST, OR PRIVATE QUOTE. The difference between a plan a school can
//  find and pick for itself, and one that only exists in a quote somebody
//  sends them. A bespoke price for one large trust is a real plan —
//  published, sellable, and deliberately not on the pricing page.
//
//  ON ITS OWN IT MAKES NOTHING BUYABLE. A plan is sellable when THREE things
//  are true:
//      status is ACTIVE          (#4 publish)
//      publiclyAvailable is true (this endpoint)
//      today is inside the selling window
//  This endpoint owns one of them. Every response says which of the other two
//  is still missing, so a public plan that is not on sale explains itself.
//
//  IT IS IDEMPOTENT, unlike #4 and #6. Those are one-way doors, so "it was
//  already done" is a fact the caller needs. This is a switch that can be
//  flipped back in one call, so a repeat costs nothing and refusing it would
//  only teach callers to read first and then race.
//
//  publiclyAvailable IS REQUIRED and boxed. An omitted boolean would arrive as
//  false — indistinguishable from deliberately hiding the plan — so a
//  forgotten field would pull a plan off the pricing page and report success.
//
// ---------------------------------------------------------------------------
// 01  PUT A PUBLISHED PLAN ON THE PUBLIC LIST              -> 200 OK
//     Run Create Plan Draft, Set Plan Features, Publish Plan, then this.
//     OUT: publiclyAvailable true, sellable TRUE
//          nextStep: "Now on the public list. Schools can now pick it."
//     THIS IS THE CALL THAT FINALLY MAKES A PLAN BUYABLE.
// ---------------------------------------------------------------------------
//
// 02  SEND IT AGAIN                                        -> 200 OK
//     IDEMPOTENT. "It was already on the public list. Schools can now pick
//     it."
// ---------------------------------------------------------------------------
//
// 03  TAKE IT OFF THE LIST                                 -> 200 OK
// {
//   "publiclyAvailable": false
// }
//     OUT: sellable false
//          "Taken off the public list. It can still be offered privately in a
//           quote. It is not sellable: a plan has to be on the public list to
//           be picked."
//     The plan is still ACTIVE and still real — just not advertised.
// ---------------------------------------------------------------------------
//
// 04  ON A DRAFT                                           -> 200 OK
//     Set it on a draft before publishing. ALLOWED, so the decision can be
//     made before the plan goes live.
//     OUT: publiclyAvailable true, sellable FALSE
//          "Now on the public list. It is NOT sellable yet — it is still a
//           DRAFT. Publish it to put it on sale."
// ---------------------------------------------------------------------------
//
// 05  ON A PLAN WITH A FUTURE LAUNCH DATE                  -> 200 OK
//     Set effectiveFrom to 2030 with #2, publish, then this.
//     OUT: ACTIVE, public true, sellable FALSE
//          "Now on the public list. It is not sellable yet: it goes on sale on
//           2030-01-01T00:00:00Z."
//     All three facts reported separately, so nothing looks broken.
// ---------------------------------------------------------------------------
//
// 06  LISTING A RETIRED PLAN                           -> 409 Conflict
//     Retire it with #6 first, then send true.
//     OUT: { "code": "PLAN_RETIRED",
//            "message": "... is retired, so nobody can buy it. Listing it
//                        publicly would advertise a plan every purchase would
//                        refuse." }
// ---------------------------------------------------------------------------
//
// 07  UNLISTING A RETIRED PLAN                             -> 200 OK
// {
//   "publiclyAvailable": false
// }
//     ALLOWED. Only the "on" direction is refused — taking a retired plan off
//     the list is tidying up, and never wrong.
//     OUT: "Taken off the public list. It is not sellable, and cannot become
//           sellable: it is retired."
//     Note it does NOT say "can still be offered privately" here: a retired
//     plan cannot be sold at all.
// ---------------------------------------------------------------------------
//
// 08  AN EMPTY BODY                                  -> 400 Bad Request
// {
// }
//     OUT: fieldErrors: { "publiclyAvailable": ["must not be null"] }
//     The one field is required — there is no partial case for a PATCH whose
//     only field is the thing being set.
// ---------------------------------------------------------------------------
//
// 09  NOT A BOOLEAN                                  -> 400 Bad Request
// {
//   "publiclyAvailable": "yes please"
// }
//     OUT: { "code": "MALFORMED_REQUEST" }
// ---------------------------------------------------------------------------
//
// 10  A PLAN OR VERSION THAT DOES NOT EXIST             -> 404 Not Found
//     OUT: { "code": "PLAN_NOT_FOUND" }
// ---------------------------------------------------------------------------

{
}

// ===========================================================================
//  TEST CASES  —  POST /platform/plans/{code}/versions/{version}/retire
//  Platform surface. No body needed.
// ===========================================================================
//
//  RETIRING IS ABOUT THE MENU, NOT ABOUT ANYBODY'S SUBSCRIPTION. The plan
//  stops being something a school can pick. Schools ALREADY on it keep it —
//  same price, same features — and nothing about their subscription changes.
//
//  THAT DISTINCTION IS THE WHOLE POINT. Retiring a popular plan is a routine
//  commercial decision. If it touched subscriptions it would cut off every
//  school on it at once. Cancelling one school is #19, deliberately, one
//  school at a time.
//
//  A DRAFT CAN BE RETIRED TOO, and it is the only way to withdraw one: no
//  endpoint in this module deletes anything. Nobody is on a draft, so it costs
//  nothing. The response says which of the two happened — "withdrawn before it
//  was ever sold" and "stopped being sold" are different facts.
//
//  TERMINAL. There is no un-retire, and #2, #3 and #4 all refuse a retired
//  plan afterwards.
//
//  publiclyAvailable IS LEFT ALONE. It belongs to #7, and it makes no
//  difference anyway: every list of buyable plans filters on ACTIVE first, so
//  a retired plan is off the pricing page whatever that flag says.
//
// ---------------------------------------------------------------------------
// 01  RETIRE A PUBLISHED PLAN                              -> 200 OK
//     Run Create Plan Draft, Set Plan Features, Publish Plan, then this.
//     OUT: status "RETIRED", effectiveUntil stamped with now, sellable false
//          nextStep: "Retired, and no longer on the menu ... Schools ALREADY
//                     on it keep it, at the price and features they were sold,
//                     and nothing about their subscription has changed."
// ---------------------------------------------------------------------------
//
// 02  WITHDRAW A DRAFT                                     -> 200 OK
//     Create a draft and retire it without publishing.
//     OUT: status "RETIRED"
//          nextStep: "Withdrawn. It was still a draft, so it was never sold to
//                     anybody and nothing else is affected. Its plan code
//                     stays taken."
//     NOTE the last sentence: the code is NOT released. Nothing here deletes.
// ---------------------------------------------------------------------------
//
// 03  RETIRE IT AGAIN                                  -> 409 Conflict
//     OUT: { "code": "PLAN_ALREADY_RETIRED" }
//     Not an idempotent 200: retiring is terminal, and a caller who cannot
//     tell "it was already retired" from "you just retired it" will assume the
//     wrong one.
// ---------------------------------------------------------------------------
//
// 04  AFTERWARDS, EVERYTHING IS REFUSED                -> 409 Conflict
//     PATCH the details:  PLAN_NOT_EDITABLE  "... is RETIRED and cannot be
//                                             edited."
//     PUT the features:   PLAN_NOT_EDITABLE  "... its features cannot be
//                                             changed."
//     POST publish:       PLAN_NOT_EDITABLE  "... cannot be published."
//     Retiring is not a way back to draft.
//
//     All three messages end "Make a new version of it instead" — which is #5,
//     and #5 is deferred. The advice cannot be followed yet.
// ---------------------------------------------------------------------------
//
// 05  effectiveUntil ALREADY IN THE PAST                   -> 200 OK
//     Set the window in the past with #2, then retire.
//     OUT: effectiveUntil UNCHANGED. It stopped being sold then; moving the
//     date forward to now would rewrite that.
// ---------------------------------------------------------------------------
//
// 06  effectiveUntil IN THE FUTURE                         -> 200 OK
//     Set effectiveUntil to 2030 with #2, publish, then retire.
//     OUT: effectiveUntil BROUGHT FORWARD to now — it stops being sold now,
//     not in 2030.
// ---------------------------------------------------------------------------
//
// 07  A PLAN OR VERSION THAT DOES NOT EXIST             -> 404 Not Found
//     OUT: { "code": "PLAN_NOT_FOUND" }
// ---------------------------------------------------------------------------

{
  "planCode": "{{planCode}}",
  "planVersion": 1,
  "currentPeriodStart": "2026-09-08T00:00:00Z"
}

// ===========================================================================
//  TEST CASES  —  POST /platform/schools/{id}/subscriptions
//  Platform surface. Needs {{schoolId}} and a PUBLISHED plan.
// ===========================================================================
//
//  THIS IS WHAT MAKES A SCHOOL A PAYING CUSTOMER, and it is the piece core has
//  been complaining about. activateSchool (#3 in core) was written to require
//  an active subscription, found nothing could create one, and settled for a
//  soft check — every activate response carried:
//
//    "subscriptionStatus": "NONE",
//    "subscriptionNote": "No subscription exists for this school. Activation
//     was allowed anyway because nothing creates subscriptions yet — this
//     check must become a hard requirement once it does."
//
//  Create a subscription first and the same call now reports
//  "subscriptionStatus": "ACTIVE" with no note.
//
//  IT ALSO WORKS THE OTHER WAY ROUND. A school still PROVISIONING with
//  everything else already in place is waiting only on a subscription, so
//  this endpoint activates it — see cases 12 to 14. The setup gates are not
//  skipped: no SCHOOL_ADMIN role or missing number sequences leaves the
//  school PROVISIONING, and the subscription is still created.
//
//  TWO FIELDS IS THE ORDINARY REQUEST. The plan already knows the price, the
//  currency, the billing cycle and therefore when the first period ends. The
//  rest of the fields exist for a negotiated deal.
//
//  THE PLAN IS NAMED BY CODE AND VERSION, not by a Mongo id — the same way
//  every plan URL names one.
//
//  THREE DOCUMENTS, ONE TRANSACTION: the subscription, its first
//  subscription_history row, and the number_sequences row it took
//  subscriptionNo from. A subscription with no history row is a customer
//  nobody can explain; a number handed out with no subscription attached is a
//  permanent gap in the numbering that looks like a deleted record.
//
// ---------------------------------------------------------------------------
// 01  THE ORDINARY REQUEST                                -> 201 Created
//     The body above, on a published plan.
//     OUT: subscriptionNo "SUB/2026/09/000001", status "ACTIVE", current true
//          contractedPrice = the plan's listPrice
//          currencyCode    = the plan's currency (never the caller's)
//          billingCycle    = the plan's cycle
//          currentPeriodStart = MIDNIGHT TODAY in the school's own zone, not
//                               the moment the request arrived
//          currentPeriodEnd   = start + the cycle's days (30/90/180/365),
//                               and it may NOT be sent on those four cycles
//          maxStudentsOverride / maxUsersOverride = COPIED FROM THE PLAN,
//                               since the sale named no figures of its own
//          hasLimitOverrides  = false, because they match the plan
//     Header: Location: /platform/schools/{id}/subscriptions/SUB/2026/09/000001
// ---------------------------------------------------------------------------
//
// 02  A NEGOTIATED DEAL                                   -> 201 Created
// {
//   "planCode": "{{planCode}}",
//   "planVersion": 1,
//   "trial": true,
//   "contractedPrice": 39999.50,
//   "maxStudentsOverride": 2500,
//   "maxUsersOverride": 300,
//   "autoRenew": false,
//   "billingCustomerReference": "cus_Qx7B2mR9",
//   "reason": "Pilot, 20% partner discount."
// }
//     OUT: status "TRIAL", hasLimitOverrides true, and the response shows
//          contractedPrice 39999.50 NEXT TO planListPrice 49999.00 — the only
//          way to notice a school is on a discount.
//     maxStudents comes back as 2500: the response reports the limit IN FORCE,
//     not the raw override, so no caller has to work out which applies.
// ---------------------------------------------------------------------------
//
// 03  A SECOND SUBSCRIPTION FOR THE SAME SCHOOL       -> 409 Conflict
//     Send case 01 twice.
//     OUT: { "code": "SUBSCRIPTION_ALREADY_EXISTS",
//            "message": "... is already on SUB/2026/09/000001. Change the plan on
//                        that subscription rather than creating a second
//                        one." }
//     A unique partial index enforces one current subscription per school, but
//     a duplicate-key error tells the caller nothing about what to do instead.
// ---------------------------------------------------------------------------
//
// 04  A PLAN THAT IS STILL A DRAFT                    -> 409 Conflict
//     OUT: { "code": "PLAN_NOT_SELLABLE",
//            "message": "... is DRAFT, so no school can be put on it. Publish
//                        it first." }
//
//     A RETIRED plan is also refused, with different advice — "A retired plan
//     cannot be sold again" — because telling somebody to publish a retired
//     plan sends them to an endpoint that will refuse them.
//
//     A plan that is published but NOT publicly available IS allowed: that is
//     exactly a private quote, and this is how a private quote gets sold.
// ---------------------------------------------------------------------------
//
// 05  SELL IT ON A DIFFERENT CADENCE                      -> 201 Created
//     billingCycle is optional, and absent means the plan's own. Sending one
//     sells the same plan on different terms — a school paying quarterly for
//     a plan listed yearly buys the same feature access on a different cadence.
//     It is stored on the SUBSCRIPTION, so the plan is unchanged and no other
//     school on it is affected.
//
//       { "planCode": "{{planCode}}", "planVersion": 1,
//         "billingCycle": "QUARTERLY" }
//
//     OUT: billingCycle QUARTERLY, and currentPeriodEnd is start + 90 days
//          rather than + 365 — the period follows the cycle being SOLD.
//
//     THE REFUSAL FOLLOWS IT TOO, which is the part worth testing both ways:
//       a YEARLY plan sold "CUSTOM", no date   -> 400
//                                                 BILLING_PERIOD_END_REQUIRED
//       a CUSTOM plan sold "MONTHLY", no date  -> 201, 30 days
//       a CUSTOM plan sold "MONTHLY", a date   -> 400
//                                              BILLING_PERIOD_END_NOT_ALLOWED
//
//     An unknown value is a validation error, not a silent default:
//       { "billingCycle": "WEEKLY" }           -> 400
//
// ---------------------------------------------------------------------------
// 06  A CUSTOM BILLING CYCLE                        -> 400 Bad Request
//     On a plan whose billingCycle is CUSTOM, with no currentPeriodEnd:
//     OUT: { "code": "BILLING_PERIOD_END_REQUIRED",
//            "message": "currentPeriodEnd has to be sent on a CUSTOM cadence,
//                        which has no set length to work the period out
//                        from." }
//     Guessing a month for CUSTOM would be inventing a contract term.
//
//     AND THE MIRROR: ONLY CUSTOM TAKES AN END DATE. On the four fixed
//     cadences, sending one is refused rather than honoured:
//       { "planCode": "{{planCode}}", "planVersion": 1,
//         "currentPeriodStart": "2026-10-01T00:00:00Z",
//         "billingCycle": "QUARTERLY",
//         "currentPeriodEnd": "2027-11-25T23:59:59Z" }
//       -> 400 { "code": "BILLING_PERIOD_END_NOT_ALLOWED",
//                "message": "currentPeriodEnd cannot be sent on a QUARTERLY
//                            cadence, which decides its own: QUARTERLY
//                            periods run 90 days from currentPeriodStart.
//                            Leave it out and it is worked out from the start
//                            date; move the start to move the end. Only a
//                            CUSTOM cadence takes an end date." }
//     Those four ARE their length, so a date sent with one either agrees with
//     the derivation — saying nothing — or disagrees with it, and then the
//     record contradicts itself. Refused rather than quietly dropped: a 201
//     carrying a different date than the one sent ignores the caller without
//     telling them.
//     Leave it out and the same request is 201 with start + 90 days.
// ---------------------------------------------------------------------------
//
// 07  THE PERIOD END DERIVED FROM THE CYCLE               -> 201 Created
// {
//   "planCode": "{{planCode}}", "planVersion": 1,
//   "currentPeriodStart": "2026-04-01T00:00:00Z"
// }
//     A FIXED COUNT OF DAYS, from the plan's cycle:
//       MONTHLY 30 | QUARTERLY 90 | HALF_YEARLY 180 | YEARLY 365
//     So a YEARLY plan starting 2026-04-01 ends 2027-04-01, and a MONTHLY one
//     starting 31 January ends 2 March.
//
//     EQUAL PERIODS RATHER THAN EQUAL DATES, and the drift is real: twelve
//     30-day months come to 360 days, and a 365-day year through 29 February
//     ends a day early. Adding calendar months instead makes every period a
//     different length and lands the end on a different day of the month
//     depending on where it started. Evenness was chosen.
//
//     SEND NOTHING and the period starts at MIDNIGHT TODAY in the school's
//     own zone — 06:00 in Kolkata is still yesterday in UTC, so the zone is
//     what decides which day "today" is.
// ---------------------------------------------------------------------------
//
// 08  A PERIOD THAT RUNS BACKWARDS                  -> 400 Bad Request
// {
//   "planCode": "{{planCode}}", "planVersion": 1,
//   "billingCycle": "CUSTOM",
//   "currentPeriodStart": "2027-01-01T00:00:00Z",
//   "currentPeriodEnd": "2026-01-01T00:00:00Z"
// }
//     OUT: { "code": "INVALID_BILLING_PERIOD" }
//     ON CUSTOM, which is the only cadence that takes an end date. The same
//     body on a fixed cadence is 400 BILLING_PERIOD_END_NOT_ALLOWED instead
//     — the field never reaches this check there.
// ---------------------------------------------------------------------------
//
// 09  AN OVERRIDE OF ZERO                           -> 400 Bad Request
// {
//   "planCode": "{{planCode}}", "planVersion": 1, "maxStudentsOverride": 0
// }
//     OUT: { "code": "LIMIT_TOO_LOW", "message": "... Omit it to use the
//            plan's own limit." }
//     Zero is refused HERE, unlike on #14 where it removes an override —
//     on create there is nothing to remove, so it is a mistake like any
//     other. Omitting the field copies the plan's figure instead.
//     A negative contractedPrice is PRICE_NEGATIVE, from the same validator #1
//     and #2 use.
// ---------------------------------------------------------------------------
//
// 10  A SCHOOL THAT CANNOT BE SOLD TO               -> 409 Conflict
//     A CLOSED, DELETION_PENDING or DELETED school.
//     OUT: { "code": "SCHOOL_NOT_SUBSCRIBABLE" }
//     Not reachable yet — #13 to #17 in core are deferred, so no school can
//     reach those states.
// ---------------------------------------------------------------------------
//
// 11  AN UNKNOWN SCHOOL OR PLAN                       -> 404 Not Found
//     SCHOOL_NOT_FOUND or PLAN_NOT_FOUND.
// ---------------------------------------------------------------------------
//
// 12  WHAT LANDS IN THE DATABASE
//     From mongosh, after case 01:
//       db.school_subscriptions.findOne({schoolId: "..."})
//         -> maxStudentsOverride and maxUsersOverride HOLD THE PLAN'S
//            FIGURES, not null: the subscription says what the school may use
//            without anybody reading the plan behind it, and a school already
//            sold keeps what it bought when the plan's next version moves its
//            ceiling. `hasLimitOverrides` in the response compares against
//            the plan rather than checking for null, so it still means "this
//            school's ceiling is not its plan's".
//       db.subscription_history.find({schoolSubscriptionDocsId: "..."})
//         -> one row: eventType CREATED (or TRIAL_STARTED), previousStatus
//            null — there was no status before this — newStatus ACTIVE,
//            source ADMIN_PORTAL, performedByDocsId null because nobody is
//            signed in yet.
//       db.number_sequences.findOne({schoolId: "...",
//                                    sequenceType: "SUBSCRIPTION"})
//         -> nextValue 2, prefixTemplate "SUB/{YYYY}/{MM}/"
//
//     THE HOUSE FORMAT IS XXX/{YYYY}/{MM}/ + six digits, for every kind of
//     number in the system: SUB/2026/09/000001, ADM/2026/09/000123,
//     RCPT/2026/09/000045. The trailing slash matters — the number is appended
//     straight on, so "SUB/{YYYY}/{MM}" would give SUB/2026/09000001.
//
//     NUMBERING IS PER SCHOOL. Two schools both get SUB/2026/09/000001, which
//     is correct: subscriptionNo is unique per school, not globally.
// ---------------------------------------------------------------------------
//
// 13  A PROVISIONING SCHOOL GOES LIVE                     -> 201 Created
//     A school that has had complete-provisioning run on it, so it has its
//     SCHOOL_ADMIN role and all its number sequences, but was never
//     activated. Send case 01 against it.
//     OUT: the subscription as usual, and nextStep ends with
//          "The school is now ACTIVE — a subscription was the last thing it
//           needed."
//     Then GET /platform/schools/{{schoolId}}:
//          status "ACTIVE", activatedAt stamped.
//
//     activatedAt is set only the FIRST time, so a school that is suspended
//     and later resubscribes keeps the date it originally went live.
// ---------------------------------------------------------------------------
//
// 14  A SCHOOL WHOSE SETUP IS NOT FINISHED                -> 201 Created
//     A school created by POST /platform/schools with complete-provisioning
//     NOT yet run. Send case 01 against it.
//     OUT: the subscription IS created — activation never fails the sale —
//          and nextStep carries the actual reason:
//          "The school is still PROVISIONING: This school has no SCHOOL_ADMIN
//           role. Run complete-provisioning first."
//     A school missing sequences instead reads "This school has 3 of 12
//     number sequences. Run complete-provisioning first."
//     Then GET /platform/schools/{{schoolId}}: still PROVISIONING,
//     activatedAt null.
//
//     The check is the same one #3 in core uses — whyNotReadyToActivate in
//     SchoolPlatformService — so the two endpoints cannot disagree about what
//     "ready" means. Activating a school without these produces a live school
//     that fails on first use.
// ---------------------------------------------------------------------------
//
// 15  A SCHOOL THAT IS ALREADY LIVE, OR SUSPENDED          -> 201 Created
//     Anything other than PROVISIONING is left alone.
//     OUT: nextStep says "The school itself is SUSPENDED, which a
//          subscription does not change."
//     Reinstating a suspended school is #5 in core; buying something is not
//     an appeal.
// ---------------------------------------------------------------------------
// ---------------------------------------------------------------------------
//  currentPeriodStart IS REQUIRED, ON EVERY CYCLE  -> 400 Bad Request
//     Omit it and the answer is 400 VALIDATION_FAILED naming the field.
//
//     It used to default to today and no longer does: the start is the anchor
//     the end is measured from, and on a YEARLY sale it fixes which day the
//     school is billed on for as long as it stays. Sending today explicitly
//     says the same thing the default did, and says it on purpose.
//
//     A CUSTOM cycle needs currentPeriodEnd with it as well. The other four
//     derive theirs from the start and REFUSE one — see case 06.
//
// ---------------------------------------------------------------------------
//  A BILLING PERIOD STARTS TODAY OR LATER          -> 400 Bad Request
//     { "currentPeriodStart": "<any past instant>", ... }
//       -> 400 PERIOD_START_IN_PAST
//
//     Nothing in the codebase invoices a period, so a backdated start would
//     record a school as paying for time nothing could ever charge it for —
//     a figure sitting in the record that no process could act on.
//
//     TODAY COUNTS, and "today" is the SCHOOL'S day rather than UTC's:
//       an Asia/Kolkata school's midnight is 18:30Z the previous day, and
//       that instant is ACCEPTED. One second before it is refused.
//     So a naive UTC comparison would reject the school's own today.
//
//     A future start is fine — that is how a contract beginning next month
//     is recorded.

{
  "currentPeriodStart": "2026-10-01T00:00:00Z",
  "reason": "Period pushed out three months."
}

// `reason` IS REQUIRED on every one of these. Drop it and the request is
// refused before the service sees it.

// ===========================================================================
//  TEST CASES  —  PATCH /platform/schools/{id}/subscriptions/{no}
//  Platform surface. Needs {{schoolId}} and a subscription — run Create
//  Subscription first.
// ===========================================================================
//
//  EVERY FIELD IS OPTIONAL and absent means unchanged. What each field's
//  absence means is in the description above; the cases below are what the
//  endpoint actually does with them.
//
//  THE EDITABLE FIELDS ARE SEVEN, all flat: status, billingCycle,
//  currentPeriodStart, currentPeriodEnd, autoRenew, maxStudentsOverride,
//  maxUsersOverride — plus `reason`, which is REQUIRED, is stored on the
//  subscription as reasonForChanges AND written to the history row.
//
//  NOT EDITABLE HERE: contractedPrice and currencyCode (#25),
//  billingCustomerReference (#26), the plan (#16), subscriptionNo, current
//  and schoolId. Sending them is ignored like any other unknown field.
//
//  cancelledAt AND cancellationReason NO LONGER EXIST on the model. When a
//  subscription was cancelled is the effectiveAt of its CANCELLED history
//  row; reasonForChanges holds why it was last changed, whatever the change.
//
//  ANSWERS THE WHOLE SUBSCRIPTION BACK, the same shape as Get Subscription,
//  so there is no second call to see what it now says. `note` says what moved.
//
// ---------------------------------------------------------------------------
// 01  PUSH A TRIAL'S END DATE OUT                              -> 200 OK
//     The body above. THIS IS WHAT EXTEND-TRIAL DID, and nothing else moves.
//     OUT: currentPeriodEnd 2027-12-31, daysRemaining recounted from it.
//          note: "Edited currentPeriodEnd. ..."
// ---------------------------------------------------------------------------
//
//  ONLY A TRIAL OR ACTIVE SUBSCRIPTION MAY BE EDITED
//                                    -> 409 SUBSCRIPTION_NOT_EDITABLE
//     db.school_subscriptions.updateOne(
//       { schoolId: "<id>", current: true },
//       { $set: { status: "SUSPENDED" } })
//
//     PAST_DUE   -> refused. Renew it once the bill is settled, or change
//                   its plan — both put it back to ACTIVE.
//     SUSPENDED  -> refused. Resume it to lift the suspension.
//     CANCELLED  -> refused. Change its plan to bring the school back.
//     EXPIRED    -> refused. Change its plan.
//
//     Each of those states was somebody's decision or a date arriving, and
//     each has an endpoint that OWNS the way out of it. Undoing one by
//     writing a field here would bypass that endpoint, and the history row
//     would say "edited" where the real event was "resumed" or "revived".
//     The refusal names the way out, so it is a signpost rather than a dead
//     end — and nothing is written when it refuses.
//
//     IT IS STILL A ONE-WAY DOOR THE OTHER WAY, deliberately. From TRIAL or
//     ACTIVE this endpoint can set ANY of the six statuses — which is how
//     PAST_DUE and EXPIRED get set by hand while no job exists:
//       { "status": "EXPIRED", "reason": "..." }  -> 200
//       the next PATCH on it                     -> 409
//
// ---------------------------------------------------------------------------
// 02  ASK FOR NOTHING                                    -> 400 Bad Request
// {}
//     OUT: { "code": "VALIDATION_FAILED",
//            "fieldErrors": { "reason": ["must not be blank"] } }
//     Bean validation runs before the service, so the missing reason is what
//     answers first.
// ---------------------------------------------------------------------------
//
// 02b AN EDIT WITH NO REASON                            -> 400 Bad Request
// {
//   "autoRenew": false
// }
//     OUT: the same VALIDATION_FAILED on `reason`. So is "reason": "   " —
//     it is @NotBlank, not @NotNull.
//     EVERY FIELD HERE IS SOMETHING A SCHOOL IS PAYING FOR. An unexplained
//     change to any of it is one nobody can answer for months later.
// ---------------------------------------------------------------------------
//
// 03  SEND WHAT IS ALREADY STORED                             -> 200 OK
// {
//   "autoRenew": true,
//   "reason": "This will not be stored."
// }
//     On a subscription whose autoRenew is already true.
//     OUT: note: "Nothing changed: every field sent already held that value.
//                 No history row was written."
//          reasonForChanges KEEPS whatever it had — an explanation for an
//          edit that did not happen is not worth storing.
//     "Changed" means different from what was stored, not "was mentioned in
//     the request".
// ---------------------------------------------------------------------------
//
// 04  A PERIOD THAT RUNS BACKWARDS                       -> 400 Bad Request
// {
//   "currentPeriodEnd": "2020-01-01T00:00:00Z",
//   "reason": "..."
// }
//     ON A CUSTOM SUBSCRIPTION, which is the only cadence that takes an end
//     date at all.
//     OUT: { "code": "INVALID_BILLING_PERIOD",
//            "message": "currentPeriodEnd (...) must be after
//                        currentPeriodStart (...). Editing one end of a
//                        period is checked against the other." }
//     Checked against whichever end did NOT move, so one end cannot be
//     edited past the other.
//
//     ON A FIXED CADENCE the same body is 400 BILLING_PERIOD_END_NOT_ALLOWED
//     instead — see case 05. The field never reaches the period check there.
// ---------------------------------------------------------------------------
//
// 05  AN END DATE ON A FIXED CADENCE                    -> 400 Bad Request
// {
//   "currentPeriodStart": "2026-04-01T00:00:00Z",
//   "currentPeriodEnd": "2027-03-31T23:59:59Z",
//   "reason": "..."
// }
//     ONLY A CUSTOM CADENCE TAKES AN END DATE. The four fixed cycles ARE
//     their length, so one sent with them either agrees with the derivation
//     — in which case it said nothing — or disagrees with it, and then the
//     record contradicts itself: MONTHLY beside a six-month period bills the
//     school for half a year while the document says it pays monthly.
//
//     OUT: { "code": "BILLING_PERIOD_END_NOT_ALLOWED",
//            "message": "currentPeriodEnd cannot be sent when the cadence is
//                        MONTHLY, which decides its own period end. Send
//                        currentPeriodStart instead — the end moves with it
//                        — or send billingCycle to change the cadence. Only
//                        a CUSTOM cadence takes an end date." }
//
//     REFUSED RATHER THAN QUIETLY DROPPED: answering 200 with a different
//     date than the one sent is ignoring the caller without telling them.
//
//     TO MOVE THE END, MOVE WHAT IT IS MEASURED FROM:
//       { "currentPeriodStart": "2026-04-01T00:00:00Z", "reason": "..." }
//         -> 200, and the end is re-derived from the new start — case 06.
//
//     A BARE END DATE IS REFUSED TOO:
//       { "currentPeriodEnd": "2027-03-31T23:59:59Z", "reason": "..." }
//         -> 400 on a MONTHLY/QUARTERLY/HALF_YEARLY/YEARLY subscription.
//            That is the case most callers try first.
//
//     READ AGAINST THE CADENCE AFTER THE EDIT, not the stored one:
//       { "billingCycle": "MONTHLY", "currentPeriodStart": "...",
//         "currentPeriodEnd": "...", "reason": "..." }
//         -> 400, even on a subscription currently billing CUSTOM. The pair
//            is refused as one request rather than accepted because CUSTOM
//            happened to be true when it arrived.
//     NOTHING IS WRITTEN by either refusal — verified by reading the
//     subscription back afterwards.
// ---------------------------------------------------------------------------
//
// 06  THE CADENCE DECIDES THE PERIOD                          -> 200 OK
// {
//   "billingCycle": "YEARLY",
//   "reason": "Moved to annual billing."
// }
//     THE CYCLE MOVES THE END WITH IT. An end derived as "start + 365" is
//     not the end of a MONTHLY period, so leaving it would bill the school
//     for a year while the document said it paid monthly.
//
//     OUT: billingCycle YEARLY, currentPeriodEnd = start + 365 days, and
//          note "Edited billingCycle, currentPeriodEnd" — a derived change
//          is REPORTED, never silent.
//
//     MOVING THE START does the same on the four fixed cycles:
//       { "currentPeriodStart": "2026-10-01T00:00:00Z", "reason": "..." }
//         -> on MONTHLY the end becomes 2026-10-31.
//
//     A CADENCE NAMES THE DATES IT NEEDS. Sending billingCycle without
//     currentPeriodStart is 400 PERIOD_START_REQUIRED: a period is measured
//     from its start, so the cadence cannot be set without saying when the
//     period it describes begins. Keyed on the cycle being SENT, not on it
//     changing — resending the cadence a subscription is already on is still
//     a statement about the period.
//
//     Every other edit leaves both dates alone:
//       { "autoRenew": false, "reason": "..." }          -> 200
//       { "maxStudentsOverride": 500, "reason": "..." }   -> 200
//       { "currentPeriodStart": "...", "reason": "..." }  -> 200, end
//                                                            re-derived
//     THE RULE IN ONE SENTENCE: the end moves when what it is measured from
//     moves, and at no other time.
//
//     MOVING TO CUSTOM NEEDS BOTH DATES WITH IT:
//       { "billingCycle": "CUSTOM", "reason": "..." }
//         -> 400 BILLING_PERIOD_END_REQUIRED. CUSTOM has no length, and the
//            date on record belongs to the cadence being left.
//       { "billingCycle": "CUSTOM",
//         "currentPeriodEnd": "2028-01-31T23:59:59Z", "reason": "..." }
//         -> 200.
//
//     MOVING AWAY FROM CUSTOM needs nothing extra — the new cycle's length
//     settles it — and REFUSES an end date sent with it, because the cadence
//     being moved TO is the one that decides.
//
//     A CUSTOM subscription whose START moves KEEPS its end: that date was
//     somebody's decision, not a derivation.
//
//     An edit touching neither the cycle nor the start derives nothing.
//
//     THIS REVERSES what this endpoint used to do, which was to leave the
//     dates alone on a cadence change. Reporting the derived field in the
//     changed list is what answers the original worry about a silent re-bill.
// ---------------------------------------------------------------------------
// 07  RAISE THE NEGOTIATED LIMITS                             -> 200 OK
// {
//   "maxStudentsOverride": 2500,
//   "maxUsersOverride": 300,
//   "reason": "Negotiated up at renewal."
// }
//     OUT: maxStudents 2500, hasLimitOverrides true. The response reports the
//          limit IN FORCE, so no caller works out which one applies.
// ---------------------------------------------------------------------------
//
// 08  RAISE ONE, LEAVE THE OTHER                              -> 200 OK
// {
//   "maxStudentsOverride": 4000,
//   "reason": "More intake than expected."
// }
//     OUT: the students override moves; the users override is untouched.
//     Omitting a field leaves it. There is no way to say "leave it" and
//     "clear it" with the same absent value, which is what case 08 is about.
// ---------------------------------------------------------------------------
//
// 09  TAKE ONE OVERRIDE AWAY                                  -> 200 OK
// {
//   "maxStudentsOverride": 0,
//   "reason": "Back to the plan's own limit."
// }
//     ZERO IS THE REMOVAL. OUT: maxStudentsOverride null, and maxStudents
//     back to the PLAN's own limit. The users override is untouched.
//
//     Why zero: Jackson hands the server null both for a field that was
//     omitted and for one sent as null, so "leave this alone" and "take this
//     away" arrive identical. Zero is free to mean the second because it
//     cannot mean anything else — a school permitted no students is not a
//     ceiling anybody negotiated, which is why Create Subscription refuses 0.
//
//     A NEGATIVE OVERRIDE IS STILL REFUSED:
//       { "maxUsersOverride": -5 }  ->  400 LIMIT_TOO_LOW
//     That is a typo, not an instruction.
// ---------------------------------------------------------------------------
//
// 10  CANCEL IT                                               -> 200 OK
// {
//   "status": "CANCELLED",
//   "reason": "School closed mid-year."
// }
//     OUT: status CANCELLED, reasonForChanges "School closed mid-year."
//          NO DATE IS STAMPED on the document — when it happened is the
//          effectiveAt of the history row this same request writes.
//     History: eventType CANCELLED, previousStatus ACTIVE.
//
//     NO TRANSITION RULES APPLY. All six statuses are accepted from any
//     other, because this is the override for a subscription that is already
//     wrong. Suspending properly is #19, resuming is #20.
// ---------------------------------------------------------------------------
//
// 11  THE NEXT EDIT REPLACES THE STORED REASON                -> 200 OK
// {
//   "autoRenew": false,
//   "reason": "Auto-renewal switched off at the school's request."
// }
//     Straight after case 09.
//     OUT: reasonForChanges is the NEW sentence, not "School closed
//          mid-year." Each edit explains itself; the trail of all of them is
//          the history.
// ---------------------------------------------------------------------------
//
// 12  A REASON ON ITS OWN                                -> 400 Bad Request
// {
//   "reason": "Just making a note."
// }
//     OUT: { "code": "NO_CHANGES_REQUESTED" }
//     A reason is not a change. This is the ONLY way to see that code now:
//     an empty body fails validation on `reason` first.
// ---------------------------------------------------------------------------
//
// 13  ALL SEVEN AT ONCE, ONE HISTORY ROW                      -> 200 OK
// {
//   "status": "PAST_DUE",
//   "billingCycle": "MONTHLY",
//   "currentPeriodStart": "2026-04-01T00:00:00Z",
//   "currentPeriodEnd": "2027-03-31T23:59:59Z",
//   "autoRenew": false,
//   "maxStudentsOverride": 4000,
//   "maxUsersOverride": 400,
//   "reason": "Contract renegotiated, invoice overdue."
// }
//     OUT: ONE history row for the whole edit, because it was one decision.
//          note names the cycle now disagreeing with the plan's — reported,
//          not corrected: billing a school monthly on a yearly plan is a real
//          arrangement, and rewriting it would undo a deliberate change.
//
//     From mongosh afterwards:
//       db.subscription_history.find({schoolSubscriptionDocsId: "..."})
//                              .sort({createdAt: 1})
//         -> TERMS_CHANGED  TRIAL     -> TRIAL     | Edited currentPeriodEnd.
//                                                    Trial extended three
//                                                    months.
//            CANCELLED      TRIAL     -> CANCELLED | Edited status. School
//                                                    closed mid-year.
//            RESUMED        SUSPENDED -> ACTIVE    | Edited status.
//
//     reasonForChanges IS NOT IN THE FIELD LIST, though it moves on every
//     edit — it would otherwise sit in every row next to the reason itself.
//
//     TERMS_CHANGED was added for this endpoint — the enum had only status
//     moves, so an edit either went unrecorded or borrowed a type that says
//     something untrue. A status move made here writes the type that names
//     it, so a suspension recorded through this endpoint and one recorded
//     through #19 read identically. PLAN_CHANGED is never written here: this
//     endpoint cannot move the plan.
//
//     THE reason ON THE ROW IS THE FIELD LIST PLUS THE CALLER'S WORDS,
//     always. Months later "the dates changed" is the question and "which
//     fields moved" is the answer; "renegotiated" alone does not say what.
//
//     NO ROW AT ALL when nothing changed (case 03).
// ---------------------------------------------------------------------------
// ---------------------------------------------------------------------------
//  A BILLING PERIOD STARTS TODAY OR LATER          -> 400 Bad Request
//     { "currentPeriodStart": "<any past instant>", ... }
//       -> 400 PERIOD_START_IN_PAST
//
//     Nothing in the codebase invoices a period, so a backdated start would
//     record a school as paying for time nothing could ever charge it for —
//     a figure sitting in the record that no process could act on.
//
//     TODAY COUNTS, and "today" is the SCHOOL'S day rather than UTC's:
//       an Asia/Kolkata school's midnight is 18:30Z the previous day, and
//       that instant is ACCEPTED. One second before it is refused.
//     So a naive UTC comparison would reject the school's own today.
//
//     A future start is fine — that is how a contract beginning next month
//     is recorded.
//     ON AN EDIT, only a start being SET is checked. The stored one is in
//     the past by definition once the period is running, and refusing that
//     would make every other field on this endpoint unreachable:
//       { "autoRenew": false, "reason": "..." }        -> 200, not blocked
//       { "currentPeriodEnd": "...", "reason": "..." }  -> 200, not blocked
//       { "currentPeriodStart": "<past>", "reason": "..." }
//                                                       -> 400

{
  "planCode": "PREMIUM",
  "planVersion": 1,
  "reason": "Outgrew Starter's 500 students.",
  "currentPeriodStart": "2026-10-01T00:00:00Z"
}

// ===========================================================================
//  TEST CASES  —  POST /platform/schools/{id}/subscriptions/{no}/change-plan
//  Platform surface. Needs {{schoolId}} on a subscription — run Create
//  Subscription first, ideally on STARTER_PLAN so there is somewhere to go.
// ===========================================================================
//
//  REQUIRED: planCode, planVersion, reason, currentPeriodStart.
//  OPTIONAL: billingCycle, contractedPrice, maxStudentsOverride,
//            maxUsersOverride, autoRenew.
//  CUSTOM ONLY: currentPeriodEnd — required when the cadence being moved to
//            is CUSTOM, and refused on the other four.
//
//  currentPeriodStart IS REQUIRED and has to be TODAY OR LATER. It used to be
//  derived as "today" and is now stated, because it decides TWO dates: the
//  anchor the new period's end is measured from, AND the instant the row
//  being left stops serving. The closed row's end is set to it, so the two
//  periods meet — trimming the old one ordinarily, extending it when the
//  start is dated later.
//
//  A future start does NOT delay the plan change. The pointer moves now; the
//  start moves when the new billing PERIOD opens.
//
//  billingCycle is optional and absent takes the NEW PLAN'S cadence. Send one
//  to move the school on at a different cadence — stored on the subscription,
//  so the plan itself is unchanged. Whichever applies decides the period, and
//  therefore whether currentPeriodEnd may be sent at all:
//      a CUSTOM plan                    -> an end date is REQUIRED
//      a YEARLY plan billed CUSTOM      -> an end date is REQUIRED
//      a CUSTOM plan billed MONTHLY     -> derived, and one sent is REFUSED
//                                          (400 BILLING_PERIOD_END_NOT_ALLOWED)
//
//  THERE IS NO TIMING FIELD. The change is immediate and the period restarts
//  with it. A subscription holds one plan, not a current one and a pending
//  one, so a scheduled change would have nowhere to live.
//
//  THERE IS NO MONEY FIELD EITHER. Nothing raises invoices, so nothing is
//  charged, credited or refunded for the period already paid for — and what
//  SHOULD happen to it is a commercial question left open on purpose.
//
// ---------------------------------------------------------------------------
// 01  THE ORDINARY UPGRADE                                    -> 200 OK
//     The body above, on a school currently on STARTER_PLAN.
//     OUT: A NEW subscriptionNo — the response is the row the school moved
//          ONTO, not the one it left. The old row is still in the
//          collection with current=false.
//          planCode PREMIUM, contractedPrice 49999 (the new plan's list),
//          billingCycle and currencyCode from the new plan,
//          maxStudents/maxUsers 2000/250 — PREMIUM's own, because the
//          request named no ceilings,
//          currentPeriodStart MIDNIGHT TODAY, currentPeriodEnd + 365 days,
//          reasonForChanges = your reason.
//          note: "Upgraded from 'STARTER_PLAN' version 1 to 'PREMIUM'
//                 version 1. ... NO money has moved for the period the
//                 school had already paid for ... What should happen to it
//                 is still an open question."
// ---------------------------------------------------------------------------
//
// 02  A REASON IS REQUIRED                              -> 400 Bad Request
// {
//   "planCode": "PREMIUM", "planVersion": 1
// }
//     OUT: { "code": "VALIDATION_FAILED",
//            "fieldErrors": { "reason": ["must not be blank"] } }
//     @NotBlank, so "  " is refused too. A plan change moves what a school
//     is entitled to and what it pays; an unexplained one is the hardest
//     record to answer questions about later.
// ---------------------------------------------------------------------------
//
// 03  NAME THE CEILINGS, OR GET THE NEW PLAN'S               -> 200 OK
// {
//   "planCode": "STARTER_PLAN",
//   "planVersion": 1,
//   "maxStudentsOverride": 4000,
//   "maxUsersOverride": 400,
//   "reason": "Downsized plan, negotiated headcount."
// }
//     OUT: maxStudents 4000 / maxUsers 400, against STARTER_PLAN's own
//          500/50. hasLimitOverrides true.
//
//     A NEGOTIATED CEILING DOES NOT SURVIVE A MOVE ON ITS OWN. Raise one
//     first with Edit Subscription:
//       PATCH .../subscriptions/current
//       { "maxStudentsOverride": 9000, "reason": "Negotiated up." }
//     then move WITHOUT naming ceilings, and the school lands on the new
//     plan's 500/50 — the 9000 is gone. Same rule as Create Subscription:
//     a ceiling is agreed against a plan, and this is a different plan.
//
//     Send only one and the other still comes from the plan: 3000 students
//     with no maxUsersOverride gives 3000/250 on PREMIUM.
//
//     ZERO IS REFUSED HERE — 400 LIMIT_TOO_LOW. There is nothing to remove
//     on a plan change; removing an override is Edit Subscription, where 0
//     means exactly that.
// ---------------------------------------------------------------------------
//
// 04  CARRY A DISCOUNT ACROSS                                 -> 200 OK
// {
//   "planCode": "PREMIUM",
//   "planVersion": 1,
//   "contractedPrice": 39999.50,
//   "reason": "Partner discount continues on the new plan."
// }
//     OUT: contractedPrice 39999.50 next to planListPrice 49999.00,
//          hasDiscount true.
//     A DISCOUNT IS NOT CARRIED OVER AUTOMATICALLY. It was agreed against a
//     plan at a price, and this is a different plan at a different price, so
//     continuing it silently would invent a deal nobody made.
// ---------------------------------------------------------------------------
//
// 04b AUTO-RENEWAL IS LEFT ALONE UNLESS YOU SAY            -> 200 OK
//     Turn it off first with Edit Subscription:
//       PATCH .../subscriptions/current
//       { "autoRenew": false, "reason": "School asked." }
//     then move plan WITHOUT the field:
// {
//   "planCode": "PREMIUM", "planVersion": 1,
//   "reason": "Upgrade, renewal untouched."
// }
//     OUT: autoRenew STILL false. This is the one field whose absence means
//     "leave it alone" rather than "take the new plan's" — a plan has no
//     opinion about renewal, and defaulting to true the way Create
//     Subscription does would switch it back on for the one school that had
//     asked for it off.
//
//     Send "autoRenew": true or false to set it as part of the move.
// ---------------------------------------------------------------------------
//
// 05  THE PLAN IT IS ALREADY ON                          -> 409 Conflict
// {
//   "planCode": "PREMIUM", "planVersion": 1, "reason": "x"
// }
//     OUT: { "code": "PLAN_UNCHANGED",
//            "message": "... is the plan this subscription is already on. To
//                        change its terms rather than its plan, use the edit
//                        endpoint." }
//     A NEWER VERSION of the same code IS allowed — that is how a school
//     moves to v2 of what it is on.
// ---------------------------------------------------------------------------
//
// 06  A PLAN THAT CANNOT BE SOLD                         -> 409 Conflict
//     A DRAFT or RETIRED target.
//     OUT: { "code": "PLAN_NOT_SELLABLE" }
//     A published plan that is NOT publicly available is allowed: that is a
//     private quote, and moving a school onto one is exactly the use.
// ---------------------------------------------------------------------------
//
// 07  A CUSTOM TARGET WITH NO END DATE                  -> 400 Bad Request
//     Moving to a plan whose billingCycle is CUSTOM:
//     OUT: { "code": "BILLING_PERIOD_END_REQUIRED" }
//     Send one, and it is used as-is:
// {
//   "planCode": "{{planCode}}", "planVersion": 1,
//   "currentPeriodStart": "2026-10-01T00:00:00Z",
//   "currentPeriodEnd": "2027-06-30T23:59:59Z",
//   "reason": "Bespoke term."
// }
//     IT IS THE NEW PLAN'S CYCLE THAT DECIDES, not the old one. A school
//     moving from a yearly plan to a monthly one gets 30 days from today.
//
//     AND THE MIRROR: A FIXED TARGET REFUSES AN END DATE.
// {
//   "planCode": "{{planCode}}", "planVersion": 1,
//   "currentPeriodStart": "2026-10-01T00:00:00Z",
//   "billingCycle": "QUARTERLY",
//   "currentPeriodEnd": "2027-10-08T23:59:59Z",
//   "reason": "Bespoke term."
// }
//       -> 400 BILLING_PERIOD_END_NOT_ALLOWED. Only a CUSTOM cadence takes
//          an end date; the other four ARE their length. Leave it out and
//          the same request is 200 with start + 90 days.
//     NOTE the ordering: PLAN_UNCHANGED is checked first, so this case needs
//     a plan the school is not already on.
// ---------------------------------------------------------------------------
//
// 08  A FINISHED SUBSCRIPTION COMES BACK                     -> 200 OK
//     On a CANCELLED or EXPIRED subscription. This used to be
//     409 SUBSCRIPTION_NOT_CHANGEABLE, which mistook what the endpoint does:
//     it never edits the row it is given, it retires that row and opens a
//     new one, so the state the old row ended in does not constrain the new
//     one at all.
//
//     Cancel Subscription with immediate: true, then send the body above.
//     OUT: 200. THE NEW ROW IS ALWAYS ACTIVE, whatever the old one was —
//          true of every plan change, not just a revival: TRIAL, SUSPENDED,
//          PAST_DUE and CANCELLED all come out ACTIVE, because a plan change
//          is somebody buying this school a plan. For a TRIAL that is the
//          conversion path, which is why Activate (#15) was withdrawn. It
//          also agrees with what this endpoint does to the school.
//
//          Two things are specific to reviving a FINISHED row:
//            autoRenew  true unless the request names it — Cancel turns it
//                       off on its way out, and carrying that forward would
//                       apply half of a decision this request reverses
//            the closed row's currentPeriodEnd  LEFT ALONE rather than
//                       trimmed to the new start: it really did stop when it
//                       was cancelled, and moving its end forward would
//                       claim it covered a gap the school was on nothing for
//
//     CHECK: db.subscription_history.findOne({ eventType: "PLAN_CHANGED" })
//              -> previousStatus CANCELLED, newStatus ACTIVE. The only place
//                 a plan change moves the status.
//            GET /schools/current/subscription/feature-access
//              -> active false before, TRUE after.
//
//     An EXPIRED one comes back the same way, and every other status still
//     carries over untouched: TRIAL stays TRIAL, SUSPENDED stays SUSPENDED.
// ---------------------------------------------------------------------------
//
// 09  WHAT LANDS IN THE DATABASE
//     TWO ROWS PER CHANGE. From mongosh, after a sale and two changes:
//       db.school_subscriptions.find({schoolId: "..."}).sort({createdAt:1})
//         -> SUB/2026/09/000001 STARTER_PLAN current false  (closed)
//            SUB/2026/09/000002 PREMIUM      current false  (closed)
//            SUB/2026/09/000003 STARTER_PLAN current TRUE   (live)
//       Exactly one current=true, always. A closed row keeps its status:
//       superseded is not expired and not cancelled.
//
//     From mongosh:
//       db.subscription_history.find({schoolSubscriptionDocsId: "..."})
//                              .sort({createdAt: 1})
//         -> PLAN_CHANGED, with BOTH plan ids on the row:
//            previousPlanDefinitionDocsId and newPlanDefinitionDocsId, and
//            previousStatus == newStatus, because a plan change is not a
//            status move.
//            reason: "Moved from 'STARTER_PLAN' version 1 to 'PREMIUM'
//                     version 1, immediately. Outgrew Starter's 500
//                     students."
//
//     db.subscription_invoices IS NOT TOUCHED. Nothing writes it yet, which
//     is why there is no money field on the request.
// ---------------------------------------------------------------------------

{
  "currentPeriodEnd": "2027-03-31T23:59:59Z"
}

// ===========================================================================
//  THE BODY ABOVE IS FOR A CUSTOM CYCLE ONLY. For the four fixed cycles,
//  DELETE IT and send nothing at all.
//
//  TEST CASES  —  POST /platform/schools/{id}/subscriptions/current/renew
//  Platform surface. Needs {{schoolId}} on a subscription — run Create
//  Subscription first.
// ===========================================================================
//
//  ONE OPTIONAL FIELD, and the ordinary renewal omits the body entirely: a
//  renewal is the same plan at the same price for the next period. The plan,
//  version, price, currency, both ceilings, the cycle, autoRenew and the
//  billing customer reference all carry across UNTOUCHED — including
//  negotiated ones, because nobody agreed to renegotiate anything by
//  renewing.
//
//  Anything that could change one of those would make it a change rather
//  than a renewal:
//      the terms -> Edit Subscription (#14)
//      the plan  -> Change Plan (#16)
//
//  currentPeriodEnd  REQUIRED on a CUSTOM cycle, which has no length for
//                    anything to derive from. On MONTHLY / QUARTERLY /
//                    HALF_YEARLY / YEARLY it is REFUSED — 400
//                    BILLING_PERIOD_END_NOT_ALLOWED — because those four
//                    decide their own length. So sending no body at all is
//                    not merely the ordinary call there; it is the only one.
//
//                    { "currentPeriodEnd": "2027-06-30T23:59:59Z" }
//                      -> on a MONTHLY subscription, 400, and NOTHING is
//                         written: the ended period is left exactly as it
//                         was, verified by reading it back.
//                      -> the same subscription with no body at all: 200,
//                         the next period starting where the last ended and
//                         running 30 days.
//
//  IT WRITES TWO ROWS. The period that ended is closed (current=false, dates
//  left alone) and a new row opens with its own subscriptionNo, starting
//  exactly where the old one ended. So no day is unbilled and none is billed
//  twice.
//
//  NO INVOICE, NO MONEY. subscription_invoices has no repository and no
//  writer anywhere in the codebase, and subTotal/taxAmount/dueDate are
//  commercial decisions rather than derivations from a plan's price. This
//  moves the billing period and records the renewal; it does not charge for
//  it, and the note says so on every response.
//
//  MOST TEST CASES NEED THE PERIOD IN THE PAST, because a live period is
//  refused. From mongosh:
//
//      db.school_subscriptions.updateOne(
//        { schoolId: "<id>", current: true },
//        { $set: { currentPeriodEnd: new Date("2026-08-01T00:00:00Z") } })
//
//  USE new Date(...), NOT { $date: ... }. Extended JSON inside a mongosh
//  --eval is stored as a literal subdocument, which then fails to map back to
//  Instant — it shows up as a 500 on the next read, not as a bad write.
//
// ---------------------------------------------------------------------------
// 01  THE ORDINARY RENEWAL                                     -> 200 OK
//     Put the period in the past (above), then send with no body.
//     OUT: a NEW subscriptionNo — the response is the row the school moved
//          onto. status ACTIVE, currentPeriodStart == the old row's
//          currentPeriodEnd exactly, currentPeriodEnd + the cycle's days
//          (30 / 90 / 180 / 365).
//          reasonForChanges: "Renewed from SUB/... on the same terms."
//          note: "Renewed on the same terms: ... NO invoice was raised and
//                 no money was taken ..."
//     CHECK: db.school_subscriptions.find({ schoolId: "<id>" })
//              -> two rows, exactly one with current: true
//              -> the closed row keeps its own dates AND its status: it was
//                 renewed, not expired and not cancelled
//
// ---------------------------------------------------------------------------
// 02  THE TERMS CARRY ACROSS UNTOUCHED                         -> 200 OK
//     Sell with negotiated terms first — contractedPrice, maxStudentsOverride
//     and maxUsersOverride all different from the plan's own figures — then
//     renew and compare with what Get Subscription said before.
//     OUT: planCode, planVersion, billingCycle, contractedPrice,
//          currencyCode, maxStudents, maxUsers, maxStudentsOverride,
//          maxUsersOverride, hasLimitOverrides, autoRenew  -> all IDENTICAL.
//          subscriptionNo, currentPeriodStart, currentPeriodEnd -> the only
//          three that move.
//     A renewal is NOT a renegotiation: hasLimitOverrides stays true and a
//     discount stays a discount. Change Plan is where terms are agreed again,
//     because a different plan means different terms.
//
// ---------------------------------------------------------------------------
// 03  A PERIOD STILL RUNNING                    -> 409 PERIOD_NOT_ENDED
//     Send against a freshly sold subscription, no setup at all.
//     Renewing early would insert a current row whose period starts in the
//     future, and every read of "what is this school on" would then have to
//     explain a subscription that has not begun. To move that date, use
//     Edit Subscription.
//
// ---------------------------------------------------------------------------
// 04  AUTO-RENEWAL TURNED OFF IS STILL RENEWED                 -> 200 OK
//     db.school_subscriptions.updateOne(
//       { schoolId: "<id>", current: true },
//       { $set: { autoRenew: false,
//                 currentPeriodEnd: new Date("2026-08-01T00:00:00Z") } })
//     autoRenew is NOT checked. Nothing calls this endpoint on a schedule, so
//     a renewal is always an operator deciding to renew THIS school now, and
//     refusing that over a flag would only mean editing the flag first to get
//     past the endpoint.
//     OUT: 200, and autoRenew: false carried onto the NEW row — the flag is
//          copied like every other term, not consulted and not reset.
//     Get My Subscription (#33) still tells the school its subscription does
//     not renew automatically, which is where the flag is actually surfaced.
//
// ---------------------------------------------------------------------------
// 05  STATUSES THAT DO NOT RENEW      -> 409 SUBSCRIPTION_NOT_RENEWABLE
//     Set the status and put the period in the past for each:
//       TRIAL      -> refused. No agreed next-period price. Edit its status,
//                     or change its plan.
//       SUSPENDED  -> refused. Would bill for a period the school cannot use.
//       CANCELLED  -> refused. Deliberately ended; renewing undoes a decision.
//
//     AND THE TWO THAT DO, both coming out ACTIVE:
//       PAST_DUE   -> 200. The note says the outstanding payment is NOT
//                     settled by this — nothing here takes a payment.
//       EXPIRED    -> 200. This is the case the endpoint exists to repair.
//     An EXPIRED row whose new period has just started would contradict its
//     own dates, which is why all three renewable statuses come out ACTIVE.
//
// ---------------------------------------------------------------------------
// 06  A CUSTOM CYCLE IS ASKED FOR THE DATE
//     Sell a CUSTOM-cycle plan (Create Subscription requires
//     currentPeriodEnd for one), put that end date in the past.
//
//     Send with NO body        -> 400 BILLING_PERIOD_END_REQUIRED, naming
//                                 currentPeriodEnd. An empty body and an
//                                 explicit null do the same: Jackson cannot
//                                 tell them apart, and all three mean "no
//                                 date was given".
//     Send the body above      -> 200. currentPeriodStart is the old period's
//                                 end, currentPeriodEnd is exactly the date
//                                 you sent, billingCycle is still CUSTOM.
//     A date on or before the start
//                              -> 400 INVALID_BILLING_PERIOD, and nothing is
//                                 written.
//
//     The date is never guessed. Falling back to a year, or to the length of
//     the last period, would put a date nobody signed off into a billing
//     record.
//
// ---------------------------------------------------------------------------
// 07  A PLAN THAT IS NO LONGER CURRENT       -> 409 PLAN_NOT_RENEWABLE
//     Publish a plan, sell it, put the period in the past, then Retire Plan
//     and renew.
//     -> the message names the change-plan endpoint:
//        "'X' version 1 has been retired, so SUB/... cannot be renewed onto
//         it for another period. Move this school to a current plan with the
//         change-plan endpoint instead."
//
//     Same for a plan put back to DRAFT, one past effectiveUntil, and one
//     whose effectiveFrom is still in the future.
//     CHECK: db.school_subscriptions.countDocuments({ schoolId: "<id>" })
//              -> still 1 on every one of them.
//
//     NOT refused: publiclyAvailable false. A private plan is a negotiated
//     quote, not an invalid state, and a school on one renews like any other.
//
//     A renewal re-commits the school to the SAME plan, which is why this is
//     checked here and not on Change Plan — there the plan being left can be
//     anything, because the school is leaving it.
//
// ---------------------------------------------------------------------------
// 08  A SCHOOL BEING WOUND DOWN            -> 409 SCHOOL_NOT_RENEWABLE
//     db.schools.updateOne({ _id: ObjectId("<id>") },
//                          { $set: { status: "CLOSED" } })
//     Same for OFFBOARDING, DELETION_PENDING and DELETED. The same allow-list
//     Change Plan uses — PROVISIONING, ACTIVE, SUSPENDED — for a plainer
//     reason: do not start a new billing period for a customer who is
//     leaving.
//     CHECK: db.school_subscriptions.countDocuments({ schoolId: "<id>" })
//              -> still 1. A refusal writes nothing.
//     Note this endpoint does NOT take the school ACTIVE, unlike Change Plan:
//     a renewal continues an arrangement rather than starting one.
//
// ---------------------------------------------------------------------------
// 09  CATCHING UP SEVERAL PERIODS                              -> 200 OK
//     Put the period end back far enough that two whole cycles have passed,
//     then renew repeatedly. Each call advances EXACTLY ONE period, so each
//     new row is a real record of a real period rather than one row
//     pretending to cover the whole gap. The chain stops on its own:
//
//       SUB/.../000001   ran to 2026-08-01           closed
//       SUB/.../000002   2026-08-01 -> 2026-08-31    closed by the next call
//       SUB/.../000003   2026-08-31 -> 2026-09-30    current, still running
//                                     -> a further call is 409
//                                        PERIOD_NOT_ENDED
//
//     CHECK: db.subscription_history.find({ schoolId: "<id>",
//                                           eventType: "RENEWED" })
//              -> one row per renewal, each with
//                 previousPlanDefinitionDocsId == newPlanDefinitionDocsId.
//                 That sameness is what tells a renewal from a plan change
//                 in a list of history rows.
//
// ---------------------------------------------------------------------------
// 10  NOT FOUND
//     A school id that does not exist        -> 404 SCHOOL_NOT_FOUND
//     A school with no subscription          -> 404 SUBSCRIPTION_NOT_FOUND
//     Different problems, different answers.
//
// ---------------------------------------------------------------------------
//  'current' IN THE PATH IS THE LITERAL WORD, the same as Edit Subscription
//  and Change Plan. A subscriptionNo contains slashes, and Tomcat rejects
//  them encoded in a path with 400 Invalid URI before Spring sees the
//  request.

{
  "reason": "Invoice INV/2026/08/000412 unpaid 30 days past the grace period."
}

// ===========================================================================
//  TEST CASES  —  POST /platform/schools/{id}/subscriptions/current/suspend
//  Platform surface. Needs {{schoolId}} on an ACTIVE or PAST_DUE subscription.
// ===========================================================================
//
//  WHY THIS IS NOT Edit Subscription WRITING A STATUS. #14 can put SUSPENDED
//  in the status field, and that is the problem: cutting a school off stops
//  its staff working, and it should not be reachable by the same request that
//  pushes a date out. { "status": "SUSPENDED" } on #14 moves the field and
//  NOTHING else — no school status, no SUSPENDED history event, none of the
//  refusals below. Use that to correct a record, not to cut a school off.
//
//  IT MOVES TWO DOCUMENTS, because one would stop nothing:
//      school_subscriptions.status = SUSPENDED
//          -> every feature off. #34 reads it and answers allowed:false.
//      schools.status = SUSPENDED
//          -> the TENANT blocked. requireUsable() reads it, so a
//             school-surface write answers 409 SCHOOL_NOT_EDITABLE.
//
//  Only an ACTIVE school's status moves. A PROVISIONING one was never usable,
//  and one already SUSPENDED keeps the suspendedAt it has. The note says
//  which of the three happened.
//
//  ONE FIELD, AND IT IS REQUIRED. Everything else in this module takes a
//  reason because it changed a figure; this takes one because it stopped a
//  school working. "The bill is unpaid" is not enough on its own.
//
// ---------------------------------------------------------------------------
// 01  CUT A SCHOOL OFF                                        -> 200 OK
//     A freshly sold school is often still PROVISIONING, and then only the
//     subscription moves. Force it ACTIVE to exercise the real path:
//       db.schools.updateOne({ _id: ObjectId("<id>") },
//                            { $set: { status: "ACTIVE" } })
//
//     Send the body above.
//     CHECK BOTH DOCUMENTS:
//       db.school_subscriptions.findOne({ schoolId: "<id>", current: true })
//         -> status SUSPENDED, reasonForChanges = your reason
//       db.schools.findOne({ _id: ObjectId("<id>") })
//         -> status SUSPENDED, suspendedAt stamped,
//            statusReason = your reason
//       db.subscription_history.find({ schoolId: "<id>",
//                                      eventType: "SUSPENDED" })
//         -> one row, previousStatus ACTIVE
//
//     THEN PROVE IT BLOCKS ANYTHING:
//       PATCH /schools/current/profile with X-School-Subdomain
//         -> 200 before, 409 SCHOOL_NOT_EDITABLE now, 200 after Resume.
//       GET /schools/current/subscription/feature-access
//         -> active false, allowed:false on every feature.
//
// ---------------------------------------------------------------------------
// 02  THE STATUSES THAT CANNOT BE SUSPENDED
//                                    -> 409 SUBSCRIPTION_NOT_SUSPENDABLE
//     db.school_subscriptions.updateOne(
//       { schoolId: "<id>", current: true },
//       { $set: { status: "TRIAL" } })
//
//     TRIAL      -> refused. No unpaid bill behind a trial, so this is not
//                   that decision — and refusing it is what lets Resume go
//                   straight to ACTIVE without looking anything up.
//     SUSPENDED  -> refused. Already suspended.
//     CANCELLED  -> refused. Ended rather than paused.
//     EXPIRED    -> refused.
//
//     PAST_DUE   -> 200. The ordinary case, the bill having gone unpaid.
//
// ---------------------------------------------------------------------------
// 03  A REASON IS REQUIRED                            -> 400 Bad Request
//     {}                  -> 400 VALIDATION_FAILED naming reason.
//     { "reason": "   " }  -> 400. Blank counts as missing.
//
// ---------------------------------------------------------------------------
// 04  A SCHOOL BEING WOUND DOWN         -> 409 SCHOOL_NOT_SUSPENDABLE
//     db.schools.updateOne({ _id: ObjectId("<id>") },
//                          { $set: { status: "CLOSED" } })
//     Same for OFFBOARDING, DELETION_PENDING and DELETED: a school already
//     closing is not suspended, it is going.
//     CHECK the subscription did not move -> still ACTIVE.
//
// ---------------------------------------------------------------------------
//  WHAT IT DOES NOT STOP. Nothing kills the school's live sessions and
//  nothing halts its scheduled jobs, because neither exists yet — a user
//  already signed in is refused at the next request that checks rather than
//  thrown out mid-page. The note says so on every response.
//
//  NO DATE LANDS ON THE SUBSCRIPTION: when it happened is the history row's
//  effectiveAt. The SCHOOL gets suspendedAt, because that field already
//  exists and core's own suspend maintains it.
//
//  THE PERIOD IS NOT PAUSED either, so the school loses time it has paid
//  for. Crediting that is a money decision nothing here can make.

{
  "reason": "Invoice INV/2026/08/000412 paid in full on 2026-09-08."
}

// ===========================================================================
//  TEST CASES  —  POST /platform/schools/{id}/subscriptions/current/resume
//  Platform surface. Needs {{schoolId}} on a SUSPENDED subscription — run
//  Suspend Subscription first.
// ===========================================================================
//
//  THE EXACT REVERSE OF #19 AND ONLY THAT. The subscription returns to ACTIVE
//  and the school with it. The plan, the price, the ceilings and BOTH period
//  dates are untouched: a suspension pauses access, and lifting it
//  renegotiates nothing.
//
//  IT RESUMES TO ACTIVE WITHOUT LOOKING ANYTHING UP. #19 only ever suspends
//  an ACTIVE or a PAST_DUE subscription, and a school that has paid is not
//  PAST_DUE any more — so ACTIVE is the only sensible answer. Refusing to
//  suspend a trial is what buys that.
//
// ---------------------------------------------------------------------------
// 01  SWITCH IT BACK ON                                       -> 200 OK
//     CHECK BOTH DOCUMENTS:
//       db.schools.findOne({ _id: ObjectId("<id>") })
//         -> status ACTIVE, statusReason replaced,
//            suspendedAt STILL SET — kept on purpose: that is when the
//            suspension began, and a resumed school's history is worth
//            keeping. Core's own reactivate leaves it too.
//       db.subscription_history.find({ eventType: "RESUMED" })  -> one row
//
//     COMPARE WITH WHAT Get Subscription SAID BEFORE THE SUSPENSION:
//       planCode, planVersion, billingCycle, contractedPrice, currencyCode,
//       maxStudents, maxUsers, currentPeriodStart, currentPeriodEnd,
//       subscriptionNo   -> ALL IDENTICAL.
//
//     And the collection still holds ONE row: unlike Change Plan and Renew,
//     this pair writes no second document.
//
// ---------------------------------------------------------------------------
// 02  THE STATUSES THAT CANNOT BE RESUMED
//                                      -> 409 SUBSCRIPTION_NOT_RESUMABLE
//     ACTIVE     -> refused. Nothing to resume.
//     TRIAL      -> refused. Never suspended, so not paused.
//     PAST_DUE   -> refused.
//     CANCELLED  -> refused, and the message says why: it ended rather than
//                   paused, so reopening it would be selling a period
//                   without saying so. That is Create Subscription or
//                   Change Plan.
//     EXPIRED    -> refused.
//
// ---------------------------------------------------------------------------
// 03  A REASON IS REQUIRED                            -> 400 Bad Request
//     {} -> 400 VALIDATION_FAILED naming reason.
//     A suspension and its lifting are a pair: a record that explains the
//     cut-off but not the restoration answers half the question.
//
// ---------------------------------------------------------------------------
//  THE PERIOD IS NOT EXTENDED, and that is deliberate. A school suspended
//  for three weeks comes back to the same currentPeriodEnd, having paid for
//  time it could not use. Crediting that is a MONEY decision: nothing here
//  raises or credits an invoice, so moving the end date would be this
//  endpoint inventing a refund. The note says so instead. If a credit was
//  agreed, Edit Subscription is where the date moves — deliberately, by
//  somebody, with a reason recorded.

{
  "reason": "School closing at the end of the academic year."
}

// ===========================================================================
//  TEST CASES  —  POST /platform/schools/{id}/subscriptions/current/cancel
//  Platform surface. Needs {{schoolId}} on a subscription.
// ===========================================================================
//
//  THE SCHOOL USUALLY KEEPS WORKING until the period it already paid for runs
//  out. A school cancelling mid-month has bought that month, and cutting it
//  off the same afternoon would be keeping its money and taking the product
//  away.
//
//  NO FIELD WAS ADDED for "cancelled but still running". The status goes
//  CANCELLED either way — the contract is over either way — and what decides
//  the ACCESS is currentPeriodEnd, because whyNotActive lets a cancelled
//  subscription grant until that date passes:
//
//      the default        status CANCELLED, period left alone
//                         -> access until currentPeriodEnd
//      immediate: true    status CANCELLED, period TRIMMED TO NOW
//                         -> access stops at once
//
//  The same division of labour Change Plan uses when it closes the row a
//  school leaves: the dates record the period actually served.
//
// ---------------------------------------------------------------------------
// 01  THE ORDINARY CANCELLATION                               -> 200 OK
//     The body above.
//     OUT: status CANCELLED, autoRenew false, currentPeriodEnd UNTOUCHED,
//          periodEnded false.
//
//     CHECK THE SCHOOL IS STILL WORKING — that is the point:
//       GET /schools/current/subscription/feature-access
//         -> active TRUE, every feature still allowed.
//       db.schools.findOne({ _id: ObjectId("<id>") })
//         -> status ACTIVE, untouched. This is NOT Suspend.
//       db.subscription_history.find({ eventType: "CANCELLED" })
//         -> one row, and effectiveAt is the PERIOD END rather than now —
//            the only place in this service where that field is
//            deliberately in the future.
//
//     AND THAT NOTHING UNDOES IT:
//       Renew Subscription  -> 409 SUBSCRIPTION_NOT_RENEWABLE
//       Resume Subscription -> 409 SUBSCRIPTION_NOT_RESUMABLE
//     No extra check was needed for either: both already refuse a CANCELLED
//     subscription.
//
// ---------------------------------------------------------------------------
// 02  END IT NOW INSTEAD                                      -> 200 OK
//     { "reason": "Contract terminated for cause.", "immediate": true }
//     OUT: currentPeriodEnd TRIMMED TO NOW, which is what stops the access.
//       GET /schools/current/subscription/feature-access
//         -> active FALSE. Cancelled AND the period is over.
//
//     The date the school had paid for is overwritten on the document, so the
//     history row's reason keeps it: "The period paid for ran to <date> and
//     was trimmed to the cancellation."
//
//     NO REFUND. Nothing here raises or credits an invoice, so what should
//     happen to the unused part is still an open question.
//
// ---------------------------------------------------------------------------
// 03  CANCELLING TWICE
//     Send 01 twice        -> 409 CANCELLATION_ALREADY_SCHEDULED, naming the
//                             date it runs out. A repeat changes nothing, so
//                             a 200 would claim a new reason was recorded.
//     Then send 02         -> 200. ESCALATING is a real decision, so it is
//                             allowed.
//     Once the period has lapsed:
//       db.school_subscriptions.updateOne(
//         { schoolId: "<id>", current: true },
//         { $set: { currentPeriodEnd: new Date("2026-08-01T00:00:00Z") } })
//       -> 409 SUBSCRIPTION_ALREADY_ENDED. Now there is nothing left.
//
// ---------------------------------------------------------------------------
// 04  WHAT IT ALLOWS THAT SUSPEND AND RESUME DO NOT
//     TRIAL      -> 200. A trial that did not convert ends here; Suspend
//                   refuses one, because there is no unpaid bill behind it.
//     SUSPENDED  -> 200. A school that never paid.
//     PAST_DUE   -> 200.
//     EXPIRED    -> 409 SUBSCRIPTION_ALREADY_ENDED.
//
//     AND THE SCHOOL'S OWN STATUS:
//       CLOSED / OFFBOARDING -> 200. Cancelling is PART of winding a school
//         down; refusing it would leave a closed school with a live
//         subscription nobody could end. Suspend and Resume refuse these.
//       DELETED / DELETION_PENDING -> 409 SUBSCRIPTION_NOT_CANCELLABLE.
//
// ---------------------------------------------------------------------------
// 05  A REASON IS REQUIRED                            -> 400 Bad Request
//     {} -> 400 VALIDATION_FAILED naming reason.
//     This is the one transition nothing undoes. A record of the end that
//     does not say why is the one nobody can answer for.
//
// ---------------------------------------------------------------------------
//  WHAT NOTHING DOES YET. Nothing marks a lapsed subscription EXPIRED, so a
//  cancellation that has served out its period reads CANCELLED with
//  periodEnded true rather than EXPIRED — every field correct, and still not
//  tidied away.
//
//  A JOB WILL CLOSE THESE. There is no endpoint for it: #22 (expire) was
//  dropped on 2026-09-08 because a period end passing is a date arriving
//  rather than a decision anybody makes — no reason to weigh, nothing to
//  refuse. #18 (mark-past-due) was dropped for the same reason, so PAST_DUE
//  is job territory too.
//
//  Until the job exists, read periodEnded alongside status. The record is
//  never wrong, only untidied — and Edit Subscription is the by-hand
//  override for a one-off: { "status": "EXPIRED", "reason": ... }.
//
//  AND IT DOES NOT TOUCH THE SCHOOL: this is a commercial end, not a
//  lock-out. Winding the tenant down is core's business.

{
  "name": "Term 1",
  "termCode": "TERM1",
  "sequence": 1,
  "startDate": "2026-04-01",
  "endDate": "2026-09-30"
}

// =========================================================================
//  TEST CASES  —  POST /schools/current/academic-years/{year}/terms
// Needs X-School-Subdomain and a year that is marked as running.
//
//  A TERM IS A DOCUMENT, not an embedded row. Six documents across three
//  modules store termDocsId, which is why it has an id — and why a term can
//  be renamed where a sectionNo never can.
//
//  termCode IS GIVEN, NOT DERIVED (changed 2026-09-12). Uppercase letters
//  and digits ONLY: ^[A-Z0-9]+$, 40 max. No underscore, no separator.
//  VALIDATED, NOT NORMALISED, so "term 1" is a 400 naming the field rather
//  than a silent rewrite into a code nobody typed.
//
//  name IS UNIQUE IN THE YEAR TOO (2026-09-12), case-insensitively. A report
//  card names the term, not its code, so two "Term 1"s are ambiguous in front
//  of a parent.
//
//  A RETIRED TERM KEEPS ITS CODE, ITS SEQUENCE AND ITS NAME, because none of
//  the three unique indexes filters on active. It RELEASES ITS DATES, because
//  nothing is taught in it.
//
//  THE MIXTURE IS REFUSED. One term weighted and another not computes to
//  nothing. A SHORTFALL is only a warning, because 20/80 -> 30/70 passes
//  through 110, and because a year being entered sits under 100 until the
//  last term arrives. AN EXCESS IS REFUSED: a create only ever adds to the
//  sum, so nothing has to pass through "over 100" to reach a valid set.
//
//  ADJACENCY IS NOT OVERLAP. Ending 30 Sep and starting 1 Oct is fine.
// =========================================================================
//
// -------------------------------------------------------------------------
// 01  THE FIRST TERM                                      -> 201 Created
//     The body above.
//     OUT: termDocsId, termCode TERM1 as sent, resultsLocked false and
//     active true. No weightPercent field, because none was sent.
// -------------------------------------------------------------------------
// 02  THE SECOND, STARTING THE DAY AFTER                  -> 201 Created
//     Adjacency is not overlap — the same rule core uses for years.
//
//     { "name": "Term 2", "termCode": "TERM2", "sequence": 2,
//       "startDate": "2026-10-01", "endDate": "2027-03-31" }
// -------------------------------------------------------------------------
// 03  THE CODE NEED NOT MATCH THE NAME                    -> 201 Created
//     OUT: termCode SEM2 beside a name of "Semester 2". Nothing derives
//     one from the other — which is the point: the name can be changed
//     later and the code, which records reference, cannot.
//
//     { "name": "Semester 2", "termCode": "SEM2", "sequence": 3,
//       "startDate": "2027-01-01", "endDate": "2027-01-31" }
// -------------------------------------------------------------------------
// 04  A CODE OF THE WRONG SHAPE                        -> 400 Bad Request
//     OUT: fieldErrors on termCode. @NotBlank passes — it was not blank.
//     Lowercase, spaces and underscores are refused rather than
//     normalised: a silent rewrite hands back a code nobody typed.
//
//     { "name": "Term 4", "termCode": "term 4", "sequence": 4,
//       "startDate": "2027-02-01", "endDate": "2027-02-28" }
// -------------------------------------------------------------------------
// 05  THE SAME CODE AGAIN                                 -> 409 Conflict
//     Send case 01 twice. OUT: { "code": "TERM_CODE_TAKEN" }
//     Case-folded, so "term 1" is the same code and the same refusal.
// -------------------------------------------------------------------------
// 06  A SEQUENCE ALREADY IN USE                           -> 409 Conflict
//     OUT: { "code": "TERM_SEQUENCE_TAKEN" }, naming the term that holds it.
//
//     { "name": "Extra", "termCode": "EXTRA", "sequence": 1,
//       "startDate": "2027-02-01", "endDate": "2027-02-28" }
// -------------------------------------------------------------------------
// 07  OVERLAPPING DATES                                   -> 409 Conflict
//     A single shared day is enough.
//     OUT: { "code": "TERMS_OVERLAP" }, naming the term it clashes with.
//
//     { "name": "Overlapping", "termCode": "OVERLAP", "sequence": 5,
//       "startDate": "2026-09-30", "endDate": "2026-10-05" }
// -------------------------------------------------------------------------
// 08  A RETIRED TERM KEEPS ITS CODE                       -> 409 Conflict
//     Set active:false on a term in Mongo (#7 is not built), then send its
//     name again. OUT: TERM_CODE_TAKEN, and the message says "retired" —
//     the unique index does not filter on active.
// -------------------------------------------------------------------------
// 09  BUT IT RELEASES ITS DATES                           -> 201 Created
//     Same retired term, but reuse its DATE RANGE under a new name.
//     Accepted: nothing is taught in a retired term, so the days are free.
//     This is the one rule where retired terms are treated differently.
// -------------------------------------------------------------------------
// 10  OUTSIDE THE YEAR                                    -> 409 Conflict
//     OUT: { "code": "TERM_OUTSIDE_ACADEMIC_YEAR" }, naming what it covers.
//
//     { "name": "Too early", "termCode": "TOOEARLY", "sequence": 8,
//       "startDate": "2026-03-31", "endDate": "2026-04-02" }
// -------------------------------------------------------------------------
// 11  AN INVERTED RANGE                                   -> 400 Bad Request
//     OUT: { "code": "INVALID_TERM_RANGE" } — NOT "outside the year",
//     which would be true and would say the wrong thing.
//
//     { "name": "Backwards", "termCode": "BACKWARDS", "sequence": 9,
//       "startDate": "2026-12-01", "endDate": "2026-11-01" }
// -------------------------------------------------------------------------
// 12  A WEIGHTED TERM, ALONE                              -> 201 Created
//     In a fresh year. OUT: weightPercent 20, and a WARNING saying the
//     active weights total 20%, not 100%. Reported, not refused.
//
//     { "name": "W1", "termCode": "W1", "sequence": 1, "startDate": "2026-04-01",
//       "endDate": "2026-09-30", "weightPercent": 20 }
// -------------------------------------------------------------------------
// 13  AN UNWEIGHTED TERM BESIDE IT                        -> 409 Conflict
//     After case 12. OUT: { "code": "TERM_WEIGHT_MIXED" }
//     Refused both ways round — a weighted term beside unweighted ones is
//     the same 409.
//
//     { "name": "W2", "termCode": "W2", "sequence": 2,
//       "startDate": "2026-10-01", "endDate": "2027-03-31" }
// -------------------------------------------------------------------------
// 14  AND THE ONE THAT COMPLETES THE 100                  -> 201 Created
//     weightPercent 80 after case 12's 20.
//     OUT: no warning at all, because 20 + 80 = 100.
// -------------------------------------------------------------------------
// 16  THE SAME NAME AGAIN, UNDER A NEW CODE               -> 409 Conflict
//     OUT: { "code": "TERM_NAME_TAKEN" }. The code is free, so this is NOT
//     TERM_CODE_TAKEN. Case-insensitive, so "term 1" collides with "Term 1".
//
//     { "name": "term 1", "termCode": "TERM1B", "sequence": 20,
//       "startDate": "2027-03-01", "endDate": "2027-03-05" }
// -------------------------------------------------------------------------
// 15  ONE PERCENT TOO MANY                                -> 409 Conflict
//     After case 14 the year is at 100. OUT: TERM_WEIGHTS_EXCEED_100,
//     naming what is used and what is left. Refused, unlike a shortfall:
//     a create only ever ADDS, so nothing passes through "over 100" on
//     the way to a valid set. Lower a term with #3 first.
//
//     { "name": "W3", "termCode": "W3", "sequence": 3,
//       "startDate": "2027-01-01", "endDate": "2027-01-31",
//       "weightPercent": 1 }
// -------------------------------------------------------------------------
//
//  EVERY REFUSAL
//     400 VALIDATION_FAILED                A missing name, termCode, sequence, startDate or endDate; a termCode of the wrong shape; a sequence below 1; a weightPercent outside 0-100.
//     400 INVALID_TERM_RANGE               endDate is before startDate. Equal dates are legal.
//     400 TENANT_NOT_RESOLVED              The X-School-Subdomain header is missing or blank.
//     404 SCHOOL_NOT_FOUND                 No school has that subdomain.
//     404 ACADEMIC_YEAR_NOT_FOUND          The {year} in the path is not a year of this school.
//     409 TERM_CODE_TAKEN                  That year already has that termCode — retired terms included.
//     409 TERM_NAME_TAKEN                  That year already has that name, case-insensitively — retired included.
//     409 TERM_SEQUENCE_TAKEN              Another term in the year holds that sequence — retired included.
//     409 TERMS_OVERLAP                    The dates cover a day an ACTIVE term already covers.
//     409 TERM_OUTSIDE_ACADEMIC_YEAR       The dates fall outside the year's own range.
//     409 TERM_WEIGHT_MIXED                One active term carries a weight and another does not.
//     409 TERM_WEIGHTS_EXCEED_100          This weight would take the year past 100%. A shortfall only warns; an excess does not.
//     409 SCHOOL_NOT_ACTIVE                Gate 1 — the school is suspended, closed or deleted.
//     409 SUBSCRIPTION_NOT_USABLE          Gate 2 — expired, suspended, or the period has ended.
//     409 ACADEMIC_YEAR_NOT_RUNNING        Gate 4 — the year was ended, or was never marked running.

{
  "name": "First Term"
}

// =========================================================================
//  TEST CASES  —  PATCH /schools/current/academic-years/{year}/terms/{termId}
// Needs X-School-Subdomain and a year that is marked as running.
//
//  ADDRESSED BY THE DOCUMENT ID, not by termCode. Settled 2026-09-10: the
//  rule is not "prefer codes", it is use whatever other collections already
//  store — and six documents across three modules store termDocsId.
//
//  EVERY FIELD IS OPTIONAL. Absent means leave it alone. An empty body is a
//  400 NOTHING_TO_UPDATE, not a 200, so a broken form finds out.
//
//  name IS UNIQUE IN THE YEAR, case-insensitively, and retired terms hold
//  theirs. A term may keep its OWN name: the check excludes it by id, so an
//  unchanged name beside a new date is never a conflict with itself.
//
//  NEVER termCode. A code edit orphans nothing, which is what makes it
//  dangerous: every report, export and saved filter naming the old code
//  stops matching while the database stays perfectly consistent.
//
//  NEVER sequence. It is unique per year, so term 1 becoming 2 while term 2
//  is still 2 hits the index halfway through. A reorder is #4.
//
//  THE DATES ARE A PAIR. One sent alone keeps the other, and the two are
//  then checked together — a start moved past an untouched end is a 400.
//
//  A RENAME READS THE YEAR'S TERMS, since the name has to be unique among
//  them. The year DOCUMENT is still read only when dates are sent. One
//  consequence: a rename can now carry a weight warning.
//
//  weightPercent CANNOT BE CLEARED. Removing one weight is only legal as
//  part of removing them all, which is #2.
//
//  THE WEIGHT SUM IS REPORTED, NEVER REFUSED. 20/80 -> 30/70 sits at 110
//  after the first call. #1 refuses an excess (a create only adds), #2
//  requires exactly 100 (it sees every row), #3 can do neither.
// =========================================================================
//
// -------------------------------------------------------------------------
// 01  A RENAME, AND NOTHING ELSE                          -> 200 OK
//     The body above. OUT: the new name and termCode untouched. It MAY
//     carry a weight warning: a rename reads the year's terms now, so
//     the total is known and reporting it is honest.
// -------------------------------------------------------------------------
// 02  AN EMPTY BODY                                   -> 400 Bad Request
//     OUT: { "code": "NOTHING_TO_UPDATE" }
//
//     { }
// -------------------------------------------------------------------------
// 03  A NAME CLEARED RATHER THAN REPLACED             -> 400 Bad Request
//     OUT: { "code": "TERM_NAME_REQUIRED" }. @NotBlank would not catch it:
//     the field is optional here, so "" has to be refused by hand.
//
//     { "name": "" }
// -------------------------------------------------------------------------
// 03b A NAME ANOTHER TERM ALREADY HAS                    -> 409 Conflict
//     OUT: { "code": "TERM_NAME_TAKEN" }, naming the term that holds it.
//     Case-insensitive, and a retired term still holds its name.
//
//     { "name": "Term 2" }
// -------------------------------------------------------------------------
// 04  termCode IS IGNORED, NOT REFUSED                     -> 200 OK
//     The record has no termCode field, so Jackson drops it. OUT: the name
//     changed and termCode exactly as it was.
//
//     { "name": "Renamed", "termCode": "NEWCODE", "sequence": 9 }
// -------------------------------------------------------------------------
// 05  ONE DATE, WHICH MOVES PAST THE OTHER            -> 400 Bad Request
//     Send only a startDate later than the stored endDate.
//     OUT: { "code": "INVALID_TERM_RANGE" } — the case a per-field check
//     waves through, because the field that arrived is fine on its own.
//
//     { "startDate": "2027-03-01" }
// -------------------------------------------------------------------------
// 06  DATES OUTSIDE THE YEAR                             -> 409 Conflict
//     OUT: { "code": "TERM_OUTSIDE_ACADEMIC_YEAR" }, naming what the year
//     covers. The year is read here and only here; a rename never loads it.
//
//     { "startDate": "2020-01-01", "endDate": "2020-02-01" }
// -------------------------------------------------------------------------
// 07  ONTO ANOTHER TERM'S DAYS                           -> 409 Conflict
//     A single shared day is enough. OUT: { "code": "TERMS_OVERLAP" }.
//     The term being edited is excluded, or it would overlap the version of
//     itself still in the database.
// -------------------------------------------------------------------------
// 08  A WEIGHT THAT BREAKS THE TOTAL                        -> 200 OK
//     In a year at 20/80, send 30 to the first term. ACCEPTED, with a
//     warning saying the active weights total 110%. This is the whole
//     reason #3 cannot refuse: 30/70 is only reachable through 110.
//
//     { "weightPercent": 30 }
// -------------------------------------------------------------------------
// 09  A WEIGHT INTO AN UNWEIGHTED YEAR                   -> 409 Conflict
//     OUT: { "code": "TERM_WEIGHT_MIXED" }. Refused where a broken total is
//     not: a mixture computes to nothing.
//
//     { "weightPercent": 40 }
// -------------------------------------------------------------------------
//
//  EVERY REFUSAL
//     400 NOTHING_TO_UPDATE                A body that asks for nothing.
//     400 TERM_NAME_REQUIRED               "name": "" — replaced, never removed.
//     400 VALIDATION_FAILED                A name over 120 chars, or a weightPercent outside 0-100.
//     400 INVALID_TERM_RANGE               endDate before startDate, including against an unsent field.
//     400 TENANT_NOT_RESOLVED              The X-School-Subdomain header is missing or blank.
//     404 SCHOOL_NOT_FOUND                 No school has that subdomain.
//     404 ACADEMIC_YEAR_NOT_FOUND          The {year} in the path is not a year of this school.
//     404 TERM_NOT_FOUND                   No term with that id in that year.
//     409 TERM_NAME_TAKEN                  Another term in the year has that name, case-insensitively.
//     409 TERM_OUTSIDE_ACADEMIC_YEAR       The new dates fall outside the year's range.
//     409 TERMS_OVERLAP                    The new dates cover a day another ACTIVE term covers.
//     409 TERM_WEIGHT_MIXED                A weight sent into a year whose other terms carry none.
//     409 SCHOOL_NOT_ACTIVE                Gate 1.
//     409 SUBSCRIPTION_NOT_USABLE          Gate 2.
//     409 ACADEMIC_YEAR_NOT_RUNNING        Gate 4.

// =========================================================================
//  TEST CASES  —  GET /schools/current/academic-years/{year}/terms
// A GET — no body. Needs X-School-Subdomain and a year.
//
//  PAGED, THOUGH THE PLAN SAID NOT TO BE. Nothing caps a year at four terms;
//  a school running monthly reporting periods has twelve.
//
//  FIVE FILTERS, ALL AND-ed: active, search, resultsLocked, weighted,
//  coversDate. Absent is never the same as false.
//
//  search MATCHES name OR termCode — a person types whichever they remember.
//  The needle is regex-quoted, so a stray "(" is an empty result, not a 500.
//
//  weighted ASKS exists, not ne:null. A term written before the field existed
//  has no key at all and must read as unweighted.
//
//  coversDate IS #10'S QUESTION ABOUT ANY DATE. Both ends inclusive, and no
//  time zone, because the caller names the date rather than the server.
//
//  EVERY SORT ENDS IN sequence, because PageResponse appends the fallback
//  order to whatever you name. sequence is unique in the year, so that makes
//  every sort a total order — a term name would not have.
//
//  AN UNKNOWN YEAR IS A 404, not an empty page — different facts.
// =========================================================================
//
// -------------------------------------------------------------------------
// 01  EVERY TERM IN THE YEAR                              -> 200 OK
//     No parameters. OUT: the terms in sequence order, in a page envelope.
// -------------------------------------------------------------------------
// 02  A YEAR WITH NO TERMS                                -> 200 OK
//     OUT: content: [], totalElements: 0. An empty page, never a 404.
// -------------------------------------------------------------------------
// 03  AN UNKNOWN YEAR                                     -> 404 Not Found
//     OUT: { "code": "ACADEMIC_YEAR_NOT_FOUND" } — not an empty page.
// -------------------------------------------------------------------------
// 04  ONLY THE ACTIVE ONES                                -> 200 OK
//     ?active=true, then ?active=false, then leave it off for BOTH.
// -------------------------------------------------------------------------
// 05  SEARCH BY CODE                                      -> 200 OK
//     ?search=TERM1 — matches termCode even when the name differs.
// -------------------------------------------------------------------------
// 06  SEARCH BY NAME                                      -> 200 OK
//     ?search=semester — case-insensitive, matches anywhere in the name.
// -------------------------------------------------------------------------
// 07  A STRAY REGEX CHARACTER                             -> 200 OK
//     ?search=Term (1 — an empty result, not a 500.
// -------------------------------------------------------------------------
// 08  THE FROZEN TERMS                                    -> 200 OK
//     ?resultsLocked=true — what #5 locks and #6 releases.
// -------------------------------------------------------------------------
// 09  WEIGHTED OR NOT                                     -> 200 OK
//     ?weighted=false finds terms with NO weightPercent key at all.
// -------------------------------------------------------------------------
// 10  WHICH TERM COVERS A DATE                            -> 200 OK
//     ?coversDate=2026-08-15 — both ends inclusive.
// -------------------------------------------------------------------------
// 11  FILTERS COMBINE                                     -> 200 OK
//     ?active=true&weighted=true — AND-ed. No match is an empty page.
// -------------------------------------------------------------------------
// 12  ONE PAGE AT A TIME                                  -> 200 OK
//     ?page=0&size=2, then ?page=1&size=2.
//     totalElements counts every match, not the page.
// -------------------------------------------------------------------------
// 13  A PAGE PAST THE END                                 -> 200 OK
//     ?page=99 — empty content, true total beside it. Not an error.
// -------------------------------------------------------------------------
// 14  A BAD PAGE OR SIZE                                  -> 400 Bad Request
