// =========================================================================
//  TEST CASES  —  POST /schools/current/academic-years/{year}/classes/{id}/subjects
// Needs X-School-Subdomain, a year, and a class id from Create Class.
//
//  CLASS-WIDE OR PER-SECTION, NEVER BOTH. Leave sectionNo out and the whole
//  class studies it. Name a section and only that section does. The same
//  subjectCode cannot do both — 409, because a section studies its own rows
//  AND the class's, so it would get the subject twice.
//
//  THE KEY IS THE PAIR (subjectCode, sectionNo). HINDI for A and HINDI for B
//  are two rows. A second HINDI for A is a 409.
//
//  subjectCode IS NORMALISED: uppercased, non-alphanumerics to underscore.
//  "maths-2" is stored MATHS_2. sectionNo is NOT — it is matched case-
//  insensitively and stored the way the class spells it.
//
//  TEACHERS AND THE GRADING SCHEME ARE CHECKED AGAINST THIS SCHOOL. Another
//  school's real id is a 404. The same teacher twice is a 400, not collapsed.
// =========================================================================
//
// -------------------------------------------------------------------------
// 01  A SUBJECT FOR THE WHOLE CLASS                       -> 201 Created
//     The body above — no sectionNo, so every section studies it.
//     OUT: the class's WHOLE subject list, with subjectCount and activeCount.
//     The row comes back with no sectionNo field at all, not a null one.
// -------------------------------------------------------------------------
// 02  THE CODE IS NORMALISED                              -> 201 Created
//     OUT: subjectCode is MATHS_2 — uppercased, the hyphen an underscore.
//     name carries the display value, which is why the code can be a code.
//
//     {
//       "subjectCode": "maths-2",
//       "name": "Maths 2",
//       "subjectType": "ELECTIVE"
//     }
// -------------------------------------------------------------------------
// 03  A CODE WITH NOTHING IN IT                           -> 409 Conflict
//     OUT: { "code": "SUBJECT_CODE_INVALID" }
//     Normalising leaves an empty string. @NotBlank passes — it was not blank.
//
//     {
//       "subjectCode": "!!!",
//       "name": "Nonsense",
//       "subjectType": "CORE"
//     }
// -------------------------------------------------------------------------
// 04  A SUBJECT FOR ONE SECTION                           -> 201 Created
//     Needs a section from Add Section first.
//     OUT: the row carries sectionNo: "A".
//
//     {
//       "subjectCode": "HINDI",
//       "name": "Hindi",
//       "subjectType": "LANGUAGE",
//       "sectionNo": "A"
//     }
// -------------------------------------------------------------------------
// 05  THE SAME SUBJECT FOR ANOTHER SECTION                -> 201 Created
//     Allowed — the key is the PAIR, not the code. This is how two sections
//     get different teachers for one subject.
//
//     {
//       "subjectCode": "HINDI",
//       "name": "Hindi",
//       "subjectType": "LANGUAGE",
//       "sectionNo": "B"
//     }
// -------------------------------------------------------------------------
// 06  THE SAME PAIR AGAIN, IN LOWER CASE                  -> 409 Conflict
//     Send case 04 with sectionNo "a".
//     OUT: { "code": "SUBJECT_ALREADY_ASSIGNED" } — "a" is section A.
//
//     {
//       "subjectCode": "HINDI",
//       "name": "Hindi",
//       "subjectType": "LANGUAGE",
//       "sectionNo": "a"
//     }
// -------------------------------------------------------------------------
// 07  PER-SECTION WHEN IT IS ALREADY CLASS-WIDE           -> 409 Conflict
//     After case 01. OUT: { "code": "SUBJECT_ASSIGNMENT_CONFLICT" }
//     Section A already studies it through the class-wide row.
//
//     {
//       "subjectCode": "MATHEMATICS",
//       "name": "Mathematics",
//       "subjectType": "CORE",
//       "sectionNo": "A"
//     }
// -------------------------------------------------------------------------
// 08  CLASS-WIDE WHEN IT IS ALREADY PER-SECTION           -> 409 Conflict
//     After case 04 — the same refusal the other way round.
//     OUT: { "code": "SUBJECT_ASSIGNMENT_CONFLICT" }
//     Both directions, because either one gives a section the subject twice.
//
//     {
//       "subjectCode": "HINDI",
//       "name": "Hindi",
//       "subjectType": "LANGUAGE"
//     }
// -------------------------------------------------------------------------
// 09  A SECTION THE CLASS DOES NOT HAVE                   -> 404 Not Found
//     OUT: { "code": "SECTION_NOT_FOUND" }
//     A typo here would otherwise sit unnoticed until a timetable was built
//     and the subject turned out to be taught to nobody.
//
//     {
//       "subjectCode": "SCIENCE",
//       "name": "Science",
//       "subjectType": "CORE",
//       "sectionNo": "Z"
//     }
// -------------------------------------------------------------------------
// 10  ANOTHER SCHOOL'S TEACHER                            -> 404 Not Found
//     A REAL staff id belonging to a different school.
//     OUT: { "code": "STAFF_NOT_FOUND" } — the lookup carries schoolId.
//     Same shape for gradingSchemeDocsId: GRADING_SCHEME_NOT_FOUND.
//
//     {
//       "subjectCode": "ART",
//       "name": "Art",
//       "subjectType": "ACTIVITY",
//       "teacherDocsIds": ["67aa15d9dc3f7d0011111111"]
//     }
// -------------------------------------------------------------------------
// 11  THE SAME TEACHER TWICE                              -> 400 Bad Request
//     OUT: { "code": "DUPLICATE_TEACHER" }
//     Refused rather than collapsed — a list that quietly loses an entry is
//     one nobody notices.
//
//     {
//       "subjectCode": "ART",
//       "name": "Art",
//       "subjectType": "ACTIVITY",
//       "teacherDocsIds": ["67aa15d9dc3f7d0011111111", "67aa15d9dc3f7d0011111111"]
//     }
// -------------------------------------------------------------------------
// 12  A YEAR THAT HAS BEEN ENDED                          -> 409 Conflict
//     Run POST /academic-years/{name}/end first.
//     OUT: { "code": "ACADEMIC_YEAR_NOT_RUNNING" } — gate 4.
//     Then read the class: a suspended or ended year still READS fine.
// -------------------------------------------------------------------------
//
//  EVERY REFUSAL
//     400 VALIDATION_FAILED                No subjectCode, name or subjectType, one over its length, or a subjectType outside the five.
//     400 DUPLICATE_TEACHER                The same staff id appears twice in teacherDocsIds.
//     400 TENANT_NOT_RESOLVED              The X-School-Subdomain header is missing or blank.
//     404 SCHOOL_NOT_FOUND                 No school has that subdomain.
//     404 ACADEMIC_YEAR_NOT_FOUND          The {year} in the path is not a year of this school.
//     404 CLASS_NOT_FOUND                  No class with that id in that year — including a real id under the wrong year, or another school's.
//     404 SECTION_NOT_FOUND                The sectionNo sent is not a section of this class. Leave it out for a class-wide subject.
//     404 STAFF_NOT_FOUND                  No such staff in this school, including another school's real id.
//     404 GRADING_SCHEME_NOT_FOUND         No such grading scheme in this school, including another school's real id.
//     409 SUBJECT_CODE_INVALID             The code has no letter or digit left after normalising.
//     409 SUBJECT_ALREADY_ASSIGNED         That exact (subjectCode, sectionNo) pair is already on the class.
//     409 SUBJECT_ASSIGNMENT_CONFLICT      The subject is already assigned the other way round.
//     409 SCHOOL_NOT_ACTIVE                Gate 1 — the school is suspended, closed or deleted.
//     409 SUBSCRIPTION_NOT_USABLE          Gate 2 — expired, suspended, or the period has ended.
//     409 ACADEMIC_YEAR_NOT_RUNNING        Gate 4 — the year was ended by POST .../end.

