// =========================================================================
//  TEST CASES  —  PATCH /schools/current/academic-years/{year}/classes/{id}/subjects/{subjectCode}?sectionNo=
// Needs X-School-Subdomain, a year, a class id, and a subject from Add Subject.
//
//  THE PAIR IS THE ADDRESS. subjectCode in the path, sectionNo in the query.
//  Leave sectionNo off for the class-wide row; blank reads the same as off.
//  The code is normalised, so the URL that created "maths-2" finds MATHS_2.
//
//  A 404 SAYS WHICH WAY ROUND IT IS. #22 forbids both at once, so asking the
//  wrong way gets "drop ?sectionNo=" or "use ?sectionNo=A" in the message.
//
//  FOUR FIELDS ONLY. Not subjectCode or sectionNo — they are the key, and a
//  move is #26 then #22. Not teacherDocsIds — that is #25. Not active — that
//  is #26 and #27. Sending them is IGNORED, not refused.
//
//  "" CLEARS shortName AND gradingSchemeDocsId. "" ON name IS A 400.
//  Clearing the scheme falls back to the exam's, which is not "no grading".
//
//  AN EMPTY BODY IS A 400, not a no-op 200.
// =========================================================================
//
// -------------------------------------------------------------------------
// 01  RENAME THE CLASS-WIDE ROW                          -> 200 OK
//     The body above, with no sectionNo.
//     OUT: the class's WHOLE subject list, like #22 answers.
//     The short name, type, teachers, scheme and active flag are untouched.
// -------------------------------------------------------------------------
// 02  ALL FOUR FIELDS AT ONCE                            -> 200 OK
//     Everything this endpoint can change, in one call.
//
//     {
//       "name": "Mathematics",
//       "shortName": "Mth",
//       "subjectType": "ELECTIVE",
//       "gradingSchemeDocsId": "67aa15d9dc3f7d0033333333"
//     }
// -------------------------------------------------------------------------
// 03  ONE SECTION'S ROW                                  -> 200 OK
//     ?sectionNo=A with a subject assigned to section A.
//     OUT: only that row changed — section B's row for the same code is
//     untouched, which is what the pair being the key means.
//
//     {
//       "name": "Hindi (Section A)"
//     }
// -------------------------------------------------------------------------
// 04  THE SECTION IN LOWER CASE                          -> 200 OK
//     ?sectionNo=a finds section A's row. Matched case-insensitively, and
//     the stored sectionNo never changes.
// -------------------------------------------------------------------------
// 05  A BLANK SECTION PARAMETER                          -> 200 OK
//     ?sectionNo= with nothing after it reaches the CLASS-WIDE row — the
//     same as leaving the parameter off entirely.
// -------------------------------------------------------------------------
// 06  THE CODE AS IT WAS TYPED INTO #22                  -> 200 OK
//     Add a subject with subjectCode "maths-2", then PATCH .../maths-2.
//     It is normalised to MATHS_2 and found. The create URL is a valid
//     edit URL.
// -------------------------------------------------------------------------
// 07  ASKING FOR A SECTION WHEN IT IS CLASS-WIDE         -> 404 Not Found
//     ?sectionNo=A on a subject assigned to the whole class.
//     OUT: { "code": "SUBJECT_NOT_FOUND" }
//     The message says "drop ?sectionNo=" — #22 forbids both at once, so
//     the row it is asking about cannot exist.
// -------------------------------------------------------------------------
// 08  ASKING CLASS-WIDE WHEN IT IS PER-SECTION           -> 404 Not Found
//     No sectionNo, on a subject assigned to section A.
//     OUT: the message names the section to use — "use ?sectionNo=A".
// -------------------------------------------------------------------------
// 09  CLEARING THE OPTIONAL FIELDS                       -> 200 OK
//     "" removes both. Clearing the scheme is not "no grading" — the
//     resolution order falls through to Exam.gradingSchemeDocsId.
//
//     {
//       "shortName": "",
//       "gradingSchemeDocsId": ""
//     }
// -------------------------------------------------------------------------
// 10  CLEARING THE NAME                                  -> 400 Bad Request
//     OUT: { "code": "SUBJECT_NAME_REQUIRED" }
//     Refused rather than cleared — the model requires a name, and it is
//     the only thing on the row a person reads. Only spaces is the same.
//
//     {
//       "name": ""
//     }
// -------------------------------------------------------------------------
// 11  AN EMPTY BODY                                      -> 400 Bad Request
//     OUT: { "code": "NOTHING_TO_UPDATE" }
//     A PATCH that changes nothing and answers 200 lets a client with a
//     broken form look healthy. An all-null body is the same refusal.
//
//     {}
// -------------------------------------------------------------------------
// 12  THE FIELDS THIS ENDPOINT WILL NOT CHANGE           -> 200 OK
//     Sent alongside a real edit. All four are IGNORED, not refused — the
//     code and section are the key, teachers are #25, active is #26/#27.
//     OUT: only name changed; no RENAMED row appeared, teachers survived.
//
//     {
//       "subjectCode": "RENAMED",
//       "sectionNo": "A",
//       "teacherDocsIds": [],
//       "active": false,
//       "name": "Only this one lands"
//     }
// -------------------------------------------------------------------------
// 13  ANOTHER SCHOOL'S GRADING SCHEME                    -> 404 Not Found
//     A REAL grading scheme id belonging to a different school.
//     OUT: { "code": "GRADING_SCHEME_NOT_FOUND" } — the lookup carries
//     schoolId. A refused scheme leaves the row exactly as it was.
//
//     {
//       "gradingSchemeDocsId": "67aa15d9dc3f7d0044444444"
//     }
// -------------------------------------------------------------------------
//
//  EVERY REFUSAL
//     400 NOTHING_TO_UPDATE                The body is empty, or every field in it is null.
//     400 SUBJECT_NAME_REQUIRED            name is "" or only spaces. A name cannot be removed, only replaced.
//     400 VALIDATION_FAILED                A name over 120, a short name over 40, or a subjectType outside the five.
//     400 TENANT_NOT_RESOLVED              The X-School-Subdomain header is missing or blank.
//     404 SCHOOL_NOT_FOUND                 No school has that subdomain.
//     404 ACADEMIC_YEAR_NOT_FOUND          The {year} in the path is not a year of this school.
//     404 CLASS_NOT_FOUND                  No class with that id in that year — including a real id under the wrong year, or another school's.
//     404 SUBJECT_NOT_FOUND                No row for that (subjectCode, sectionNo) pair. The message says which way round the subject IS.
//     404 GRADING_SCHEME_NOT_FOUND         No such grading scheme in this school, including another school's real id.
//     409 SCHOOL_NOT_ACTIVE                Gate 1 — the school is suspended, closed or deleted.
//     409 SUBSCRIPTION_NOT_USABLE          Gate 2 — expired, suspended, or the period has ended.
//     409 ACADEMIC_YEAR_NOT_RUNNING        Gate 4 — the year was ended by POST .../end.

// =========================================================================
//  TEST CASES  —  GET /schools/current/academic-years/{year}/classes/{id}/subjects?sectionNo=
// A GET — no body. Needs X-School-Subdomain, a year, and a class id.
//
//  ?sectionNo= NAMES AN AUDIENCE, NOT A ROW. Off or blank = every assignment
//  the class holds. Given = what that section is taught: ITS OWN ROWS PLUS
//  THE CLASS-WIDE ONES, because a row with no sectionNo applies to every one.
//
//  A STRICT MATCH WOULD HIDE MOST OF IT. On the fixture, strict returns 2 of
//  the 4 rows section A studies. A class-wide row has NO sectionNo field, so
//  a caller wanting the strict set can still filter in one line.
//
//  THIS IS THE ONE PLACE ?sectionNo= DIFFERS FROM #24, where it is half of a
//  row's key. Here it asks "taught to whom".
//
//  AN UNKNOWN SECTION IS A 404, not an empty-ish 200 — a typo would otherwise
//  look exactly like a real section with nothing of its own.
//
//  THE COUNTS DESCRIBE THE CLASS, NOT THE SLICE. subjectCount stays 5 while
//  2 rows come back.
// =========================================================================
//
// -------------------------------------------------------------------------
// 01  EVERY SUBJECT THE CLASS TEACHES                     -> 200 OK
//     No parameters.
//     OUT: every row — class-wide and per-section alike, with subjectCount
//     and activeCount. No sections[]; that is #30's job.
// -------------------------------------------------------------------------
// 02  WHAT ONE SECTION STUDIES                            -> 200 OK
//     ?sectionNo=A
//     OUT: section A's own rows AND every class-wide row. This is the whole
//     point of the endpoint — a strict match would hide most of it.
// -------------------------------------------------------------------------
// 03  ANOTHER SECTION DOES NOT SEE THE FIRST'S            -> 200 OK
//     ?sectionNo=B with a subject assigned only to A.
//     OUT: B's own rows and the class-wide ones. A's are absent.
// -------------------------------------------------------------------------
// 04  A SECTION WITH NOTHING OF ITS OWN                   -> 200 OK
//     A section that has no per-section subject.
//     OUT: the class-wide rows, NOT an empty list. It studies them like any
//     other section — which is why an unknown section must be a 404 instead.
// -------------------------------------------------------------------------
// 05  THE CLASS-WIDE ROWS ARE STILL IDENTIFIABLE          -> 200 OK
//     ?sectionNo=A, then look at the rows.
//     Those with no sectionNo field are the class's; those carrying "A" are
//     the section's. One line of filtering gets the strict set if you want it.
// -------------------------------------------------------------------------
// 06  THE COUNTS DO NOT FOLLOW THE FILTER                 -> 200 OK
//     ?sectionNo= a section with fewer rows than the class has.
//     subjects.length is 2 and subjectCount is still 5. Deliberate: "how many
//     does this class teach" is not "how many did you ask to see".
// -------------------------------------------------------------------------
// 07  THE SECTION IN LOWER CASE                           -> 200 OK
//     ?sectionNo=a finds section A. Matched case-insensitively, and padding
//     is trimmed.
// -------------------------------------------------------------------------
// 08  A BLANK PARAMETER                                   -> 200 OK
//     ?sectionNo= with nothing after it returns the WHOLE list — the same as
//     leaving the parameter off.
// -------------------------------------------------------------------------
// 09  A SECTION THE CLASS DOES NOT HAVE                   -> 404 Not Found
//     ?sectionNo=Z
//     OUT: { "code": "SECTION_NOT_FOUND" }
//     Refused rather than answered, because the class-wide rows alone look
//     exactly like a real section that has nothing of its own.
// -------------------------------------------------------------------------
// 10  A CLASS WITH NO SUBJECTS                            -> 200 OK
//     OUT: subjects: [], subjectCount: 0. An empty list, never a 404 — a
//     class created by #12 and not yet filled by #22.
// -------------------------------------------------------------------------
// 11  A SUSPENDED SCHOOL                                  -> 200 OK
//     Suspend the school, then read. No gate runs on a read: a school still
//     sees its own structure when it cannot change it.
// -------------------------------------------------------------------------
//
//  EVERY REFUSAL
//     400 TENANT_NOT_RESOLVED              The X-School-Subdomain header is missing or blank.
//     404 SCHOOL_NOT_FOUND                 No school has that subdomain.
//     404 ACADEMIC_YEAR_NOT_FOUND          The {year} in the path is not a year of this school.
//     404 CLASS_NOT_FOUND                  No class with that id in that year — including a real id under the wrong year, or another school's.
//     404 SECTION_NOT_FOUND                The sectionNo sent is not a section of this class. Leave it out to read every subject the class teaches.

// =========================================================================
//  TEST CASES  —  GET /schools/current/academic-years/{year}/classes/{id}/sections/{sectionNo}
// A GET — no body. Needs X-School-Subdomain, a year, a class id and a section number.
//
//  THE ONLY READ HERE THAT IS NOT A LIST. #30 answers "which sections are
//  there"; this answers "this one".
//
//  sectionNo IS A PATH SEGMENT, not a query parameter — it names the thing
//  being fetched. #31 uses ?sectionNo= to narrow an audience instead; three
//  endpoints, three jobs for one word.
//
//  THE CLASS COMES WITH IT. A section is embedded and has no identity away
//  from its class, so className and academicYear are in the response.
//
//  THE COUNTS DESCRIBE THE CLASS, not the section — "one of three".
//
//  THE SUBJECTS ARE NOT HERE. That is #31 with ?sectionNo=, which applies the
//  class-wide union.
// =========================================================================
//
// -------------------------------------------------------------------------
// 01  ONE SECTION                                         -> 200 OK
//     sectionNo A on a class that has it.
//     OUT: section is a single OBJECT, not a list — sectionNo, capacity,
//     classTeacherDocsId and active, with the class around it.
// -------------------------------------------------------------------------
// 02  IT IS THE ROW #30 RETURNS                           -> 200 OK
//     Read #30, then this. The section object is field-for-field the same
//     row. The shape is shared on purpose; what differs is the question.
// -------------------------------------------------------------------------
// 03  THE COUNTS ARE THE CLASS'S                          -> 200 OK
//     sectionCount is 3 on a class with three sections, even though one
//     section came back. "One of three" is what a page shows.
// -------------------------------------------------------------------------
// 04  NO SUBJECTS IN THE RESPONSE                         -> 200 OK
//     Deliberate. What a section studies is #31 with ?sectionNo=, which
//     applies the class-wide union — one place for that rule, not two.
// -------------------------------------------------------------------------
// 05  THE NUMBER IN LOWER CASE                            -> 200 OK
//     sectionNo a finds section A. Matched case-insensitively and trimmed,
//     as everywhere else in this module.
// -------------------------------------------------------------------------
// 06  A DIFFERENT SECTION                                 -> 200 OK
//     sectionNo B returns B — the check that the number is actually read
//     rather than the first section being handed back.
// -------------------------------------------------------------------------
// 07  A SECTION THE CLASS DOES NOT HAVE                   -> 404 Not Found
//     OUT: { "code": "SECTION_NOT_FOUND" }, naming the class it looked in.
// -------------------------------------------------------------------------
// 08  A SUSPENDED SCHOOL                                  -> 200 OK
//     Suspend the school, then read. No gate runs on a read.
// -------------------------------------------------------------------------
//
//  EVERY REFUSAL
//     400 TENANT_NOT_RESOLVED              The X-School-Subdomain header is missing or blank.
//     404 SCHOOL_NOT_FOUND                 No school has that subdomain.
//     404 ACADEMIC_YEAR_NOT_FOUND          The {year} in the path is not a year of this school.
//     404 CLASS_NOT_FOUND                  No class with that id in that year — including a real id under the wrong year, or another school's.
//     404 SECTION_NOT_FOUND                That class has no section with that number.

{
  "name": "CBSE Percentage Grading",
  "schemeVersion": "2026.1",
  "scaleType": "PERCENTAGE",
  "maximumValue": 100,
  "gradeBands": [
    { "gradeCode": "A1", "minimumValue": 91, "maximumValue": 100, "gradePoint": 10, "description": "Outstanding" },
    { "gradeCode": "A2", "minimumValue": 81, "maximumValue": 90, "gradePoint": 9, "description": "Excellent" },
    { "gradeCode": "B1", "minimumValue": 71, "maximumValue": 80, "gradePoint": 8, "description": "Very Good" },
    { "gradeCode": "B2", "minimumValue": 61, "maximumValue": 70, "gradePoint": 7, "description": "Good" },
    { "gradeCode": "C1", "minimumValue": 51, "maximumValue": 60, "gradePoint": 6, "description": "Fair" },
    { "gradeCode": "C2", "minimumValue": 41, "maximumValue": 50, "gradePoint": 5, "description": "Average" },
    { "gradeCode": "D", "minimumValue": 33, "maximumValue": 40, "gradePoint": 4, "description": "Below Average" },
    { "gradeCode": "E", "minimumValue": 0, "maximumValue": 32, "gradePoint": 0, "description": "Needs Improvement", "passed": false }
